window.__CH("c12",["<div class=\"hw\">G, g</div><div class=\"pos\"><i>indecl n</i></div><div class=\"def\">ラテン語アルファベットの第7字.</div>\r\n","<div class=\"hw\">gabalium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">〘植〙Arabia の香木.</div>\r\n","<div class=\"hw\">gabalus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 絞首台.</div><div class=\"def\"><num>②</num> 極悪人.</div>\r\n","<div class=\"hw\">Gabalī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ガバリー《Aquitania にいた一部族》.</div>\r\n","<div class=\"hw\">gabata</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">皿.</div>\r\n","<div class=\"hw\">Gabiī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ガビイー《Latium の町》.</div>\r\n","<div class=\"hw\">Gabīnius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ガビーニウス《ローマ人の氏族名》.</div>\r\n","<div class=\"hw\">Gabīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Gabii の.</div><div class=\"hw2\"><b>Gabīnī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Gabii の住民.</div>\r\n","<div class=\"hw\">gaesum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">(Gallia 人の)投げ槍.</div>\r\n","<div class=\"hw\">Gaetūlia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ガエトゥーリア《Gaetuli 族の国》.</div>\r\n","<div class=\"hw\">Gaetūlicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Gaetuli 族の.</div>\r\n","<div class=\"hw\">Gaetūlus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Gaetūlicus\">Gaetulicus</a>.</div>\r\n","<div class=\"hw\">Gaetūlī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ガエトゥーリー《Africa 北西部にいた一部族》.</div>\r\n","<div class=\"hw\">galacticus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">乳の(ような).</div>\r\n","<div class=\"hw\">galactītēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">乳色の宝石.</div>\r\n","<div class=\"hw\">Galaesus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ガラエスス《Tarentum 付近の川;現 Galeso》.</div>\r\n","<div class=\"hw\">Galanthis</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙ガランティス《Alcmena の侍女;Lucina によってイタチに変身させられた》.</div>\r\n","<div class=\"hw\">Galatae</div><div class=\"pos\">-ārum, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ガラタエ, <SUP>*</SUP>-タイ《ケルト系の一部族;前3世紀に Gallia から Phrygia へ移住した》.</div>\r\n","<div class=\"hw\">Galatia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ガラティア(ー)《Galatae 族の国;のちにローマの属州となった(前25年)》.</div>\r\n","<div class=\"hw\">Galaticus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Galatia の.</div>\r\n","<div class=\"hw\">Galatēa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘神話〙ガラテーア, <SUP>*</SUP>-テイア《海のニンフで, Acis の恋人;一眼の巨人 Polyphemus が片思いした》.</div>\r\n","<div class=\"hw\">galba<SUP>1</SUP></div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">太鼓腹.</div><hr><div class=\"hw\">galba<SUP>2</SUP></div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">〘動〙トネリコに穴をあける幼虫.</div>\r\n","<div class=\"hw\">Galba</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">ガルバ《Sulpicia 氏族に属する家名;特に <i>Servius Sulpicius ～</i>, ローマの第6代皇帝(在位68‐69)》.</div>\r\n","<div class=\"hw\">galbaneus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://galbanum\">galbanum</a>]</div><div class=\"def\">ガルバヌムの.</div>\r\n","<div class=\"hw\">galbanum</div><div class=\"pos\">-i, <i>n</i></div><div class=\"ori\">[<i>Gk</i><<i>Heb</i>.]</div><div class=\"def\">ガルバヌム(楓子<SUB>ふうし</SUB>香)《ゴム状樹脂;オオウイキョウ属の一種から採れる》.</div>\r\n","<div class=\"hw\">galbeum</div><div class=\"pos\">-ī, <i>n</i>, <B>-us</B> -ī, <i>m</i></div><div class=\"def\">腕バンド《装飾用または医療用》.</div>\r\n","<div class=\"hw\">galbina</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"ori\">[galbinus]</div><div class=\"def\">(<i>sc. </i> vestimenta)萌黄色の服《柔弱視された》.</div>\r\n","<div class=\"hw\">galbineus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">=<a href=\"entry://galbinus\">galbinus</a>.</div>\r\n","<div class=\"hw\">galbinus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">萌黄<SUB>もえぎ</SUB>色の.</div>\r\n","<div class=\"hw\">Galbiānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Galba の.</div><div class=\"hw2\"><b>Galbiānī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Galba の支持者たち.</div>\r\n","<div class=\"hw\">galea</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> かぶと.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘解〙帽状腱膜.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘動〙(節足動物の)外葉.</div>\r\n","<div class=\"hw\">galeātus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[↓<a href=\"entry://galeō\">galeō</a>]</div><div class=\"def\">かぶとをかぶった.</div>\r\n","<div class=\"hw\">galeō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[galea]</div><div class=\"def\">かぶとをかぶせる.</div>\r\n","<div class=\"hw\">Galeōtae</div><div class=\"pos\">-ārum, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ガレオータエ, <SUP>*</SUP>-タイ《Sicilia 島の占い師たち》.</div>\r\n","<div class=\"hw\">galeōtēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘動〙トカゲの一種.</div>\r\n","<div class=\"hw\">Galilaea</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i><<i>Heb</i>.]</div><div class=\"def\">ガリラエア, <SUP>*</SUP>-ライアー, <SUP>∥</SUP>ガリラヤ《Palaestina の北部地方》.</div>\r\n","<div class=\"hw\">Galilaeī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">Galilaea の住民.</div>\r\n","<div class=\"hw\">galla</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">〘植〙没食子<SUB>もつしょくし</SUB>, 五倍子<SUB>ふし</SUB>.</div>\r\n","<div class=\"hw\">Galla</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">Gallia 人の女.</div>\r\n","<div class=\"hw\">Gallaecia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ガッラエキア《Gallaeci 族の国》.</div>\r\n","<div class=\"hw\">Gallaecus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Gallaeci 族の.</div>\r\n","<div class=\"hw\">Gallaecī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ガッラエキー《Hispania Tarraconensis にいた一部族》.</div>\r\n","<div class=\"hw\">Gallia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ガッリア《Galli 族の地;のちにローマの属州》</div><div class=\"ex\">～ <i>Belgica</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">ガッリア・ベルギカ《Belgae 族の地》</span></div><div class=\"ex\">～ <i>Celtica</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">ガッリア・ケルティカ《ほぼ現在のフランスに相当》</span></div><div class=\"ex\">～ <i>Cisalpina</i> (<author>C<small>AES</small></author>)<span class=\"ext\">ガッリア・キサルピーナ《Alpes 山脈以南の Gallia》</span></div><div class=\"ex\">～ <i>Lugdunensis</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">ガッリア・ルグドゥーネンシス《Lugdunum 付近の Gallia》</span></div><div class=\"ex\">～ <i>Narbonensis</i> (<author>M<small>ELA</small></author>)<span class=\"ext\">ガッリア・ナルボーネンシス《現フランスの南東部》</span></div><div class=\"ex\">～ <i>Transalpina</i> (<author>C<small>AES</small></author>)<span class=\"ext\">ガッリア・トランサルピーナ《Alpes 山脈以北の Gallia》.</span></div>\r\n","<div class=\"hw\">gallica</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[Gallicus<SUP>1</SUP>]</div><div class=\"def\">(<i>sc. </i> solea)(Gallia 人の)靴, サンダル.</div>\r\n","<div class=\"hw\">gallicinium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[gallus/cano]</div><div class=\"def\">鶏の鳴く時刻, 夜明け.</div>\r\n","<div class=\"hw\">gallicula</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f dim</i></div><div class=\"ori\">[gallica]</div><div class=\"def\">(Gallia 人の小さな)靴.</div>\r\n","<div class=\"hw\">gallicus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[↓<a href=\"entry://Gallicus\">Gallicus<SUP>1</SUP></a>]</div><div class=\"def\">北微東の風.</div>\r\n","<div class=\"hw\">Gallicus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Gallia 人の, Gallia の.</div><hr><div class=\"hw\">Gallicus<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[Gallus<SUP>4</SUP>]</div><div class=\"def\">Cybele の神官たちの.</div>\r\n","<div class=\"hw\">Gallicānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Gallia の.</div><div class=\"hw2\"><b>Gallicānī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Gallia の住民.</div>\r\n","<div class=\"hw\">gallicātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">《碑》gallica をはいている.</div>\r\n","<div class=\"hw\">Gallicē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[Gallicus<SUP>1</SUP>]</div><div class=\"def\">Gallia 人のことばで.</div>\r\n","<div class=\"hw\">Gallius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Gallicus\">Gallicus<SUP>1</SUP></a>.</div><hr><div class=\"hw\">Gallius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ガッリウス《ローマ人の氏族名》.</div>\r\n","<div class=\"hw\">Galliō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\">ガッリオー《ローマ人の家名》.</div>\r\n","<div class=\"hw\">Gallograecia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ガッログラエキア《Gallograeci 族の国(=<a href=\"entry://Galatia\">Galatia</a>)》.</div>\r\n","<div class=\"hw\">Gallograecī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ガッログラエキー《Phrygia へ移住した Galli 族の一部族(=<a href=\"entry://Galatae\">Galatae</a>)》.</div>\r\n","<div class=\"hw\">gallulascō</div><div class=\"pos\">-ere, <i>intr</i></div><div class=\"ori\">[gallus]</div><div class=\"def\">(男子が)声変わりする.</div>\r\n","<div class=\"hw\">Gallulus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj dim</i></div><div class=\"def\">Gallia の, Gallia 人の.</div>\r\n","<div class=\"hw\">gallus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">おんどり, 雄鶏.</div>\r\n","<div class=\"hw\">Gallus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Gallicus\">Gallicus<SUP>1</SUP></a>.</div><hr><div class=\"hw\">Gallus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">Gallia 人.</div><hr><div class=\"hw\">Gallus<SUP>3</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ガッルス《ローマ人の家名;特に <i>C. Cornelius</i> ～,Vergilius の友人で詩人》.</div><hr><div class=\"hw\">Gallus<SUP>4</SUP></div><div class=\"pos\">-ī, <i>m</i>(通例 <i>pl</i>)</div><div class=\"def\">Cybele の神官.</div><hr><div class=\"hw\">Gallus<SUP>5</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ガッルス《Bithynia の川》.</div>\r\n","<div class=\"hw\">Gallī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ガッリー, <SUP>∥</SUP>ガリア人《主に Gallia Transalpina と Gallia Cisalpina に住んでいたケルト系一部族》.</div>\r\n","<div class=\"hw\">gallīna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[gallus]</div><div class=\"def\">めんどり.</div>\r\n","<div class=\"hw\">gallīnula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[gallina]</div><div class=\"def\">ひな鳥, ひよこ.</div>\r\n","<div class=\"hw\">gallīnāceus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://gallīna\">gallīna</a>]</div><div class=\"def\">家禽の.</div>\r\n","<div class=\"hw\">gallīnārium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[gallina]</div><div class=\"def\">鶏小屋.</div>\r\n","<div class=\"hw\">gallīnārius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[gallina]</div><div class=\"def\"><num>①</num> 家禽の.</div><div class=\"def\"><num>②</num> (G-)</div><div class=\"ex\"><i>Gallinaria insula</i> (<author>V<small>ARR</small></author>)<span class=\"ext\">ガッリーナーリア島《Liguria 沖の小島》</span></div><div class=\"ex\"><i>Gallinaria silva</i> (<author>C<small>IC</small></author>)<span class=\"ext\">ガッリーナーリアの森《Campania の Cumae 付近の森》.</span></div><hr><div class=\"hw\">gallīnārius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">家禽の世話をする人.</div>\r\n","<div class=\"hw\">Gallōnius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ガッローニウス《ローマ人の氏族名》.</div>\r\n","<div class=\"hw\">galēriculum</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[galerum]</div><div class=\"def\"><num>①</num> (小さな)帽子.</div><div class=\"def\"><num>②</num> かつら.</div>\r\n","<div class=\"hw\">galērum</div><div class=\"pos\">-ī, <i>n</i>, <B>-us</B> -ī, <i>m</i></div><div class=\"ori\">[galea]</div><div class=\"def\"><num>①</num> (毛皮の)帽子.</div><div class=\"def\"><num>②</num> かつら.</div>\r\n","<div class=\"hw\">galērītus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://galērum\">galērum</a>]</div><div class=\"def\">(毛皮の)帽子をかぶった.</div>\r\n","<div class=\"hw\">Galēsus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">=<a href=\"entry://Galaesus\">Galaesus</a>.</div>\r\n","<div class=\"hw\">gamba</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(馬などの後脚の)飛節.</div>\r\n","<div class=\"hw\">gametangium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘生物〙配偶子嚢.</div>\r\n","<div class=\"hw\">gametogenesis</div><div class=\"pos\">-is, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘生物〙配偶子形成.</div>\r\n","<div class=\"hw\">gamma</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ガンマ《ギリシア語アルファベットの第3字(▷Γ, γ◁)》.</div>\r\n","<div class=\"hw\">gammātus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">gamma 形(▷Γ◁)の.</div>\r\n","<div class=\"hw\">Gamēliōn</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ガメーリオーン《Attica の第7月;現行暦の1月後半から2月前半に当たる》.</div>\r\n","<div class=\"hw\">gangaba</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">荷物運搬人.</div>\r\n","<div class=\"hw\">Gangaridae</div><div class=\"pos\">-ārum, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ガンガリダエ, <SUP>*</SUP>-ダイ《India の Ganges 河畔にいた一部族》.</div>\r\n","<div class=\"hw\">ganglion</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 〘病〙腫れ物の一種.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘解〙神経節.</div>\r\n","<div class=\"hw\">gangraena</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘病〙壊疽<SUB>えそ</SUB>.</div>\r\n","<div class=\"hw\">Gangēs</div><div class=\"pos\">-is, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ガンゲース, <SUP>∥</SUP>ガンジス川《India の大河》.</div>\r\n","<div class=\"hw\">Gangēticus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Ganges 川の.</div>\r\n","<div class=\"hw\">Gangētis</div><div class=\"pos\">-idis, <i>adj f</i></div><div class=\"def\">Ganges 川の.</div>\r\n","<div class=\"hw\">ganniō</div><div class=\"pos\">-īre, <i>intr</i></div><div class=\"def\"><num>①</num> (犬が)キャンキャン鳴く, ほえる.</div><div class=\"def\"><num>②</num> (人が)がみがみ言う, どなる.</div>\r\n","<div class=\"hw\">gannītus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[↑<a href=\"entry://ganniō\">ganniō</a>]</div><div class=\"def\"><num>①</num> (犬が)キャンキャン鳴く[ほえる]こと.</div><div class=\"def\"><num>②</num> (人が)がみがみ言うこと, どなること.</div>\r\n","<div class=\"hw\">Ganymēdēs</div><div class=\"pos\">-is, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘神話〙ガニュメーデース《Troja の王 Tros(または Laomedon)の息子;Juppiter が Ida 山から天上界へ奪い去って酌をさせた美少年》.</div>\r\n","<div class=\"hw\">Garamantes</div><div class=\"pos\">-um, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ガラマンテス《Africa の内陸部にいた一部族》.</div>\r\n","<div class=\"hw\">Garamanticus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> Garamantes 族の.</div><div class=\"def\"><num>②</num> Africa の.</div>\r\n","<div class=\"hw\">Garamantis</div><div class=\"pos\">-idis, <i>adj f</i></div><div class=\"def\">=<a href=\"entry://Garamanticus\">Garamanticus</a>.</div>\r\n","<div class=\"hw\">garcifer</div><div class=\"pos\">-ferī, <SUP>◇</SUP><i>m</i></div><div class=\"def\">=<a href=\"entry://garciō\">garcio</a>.</div>\r\n","<div class=\"hw\">garciō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>m</i></div><div class=\"def\">従者, 従僕.</div>\r\n","<div class=\"hw\">Gargaphiē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ガルガピエー《Boeotia の谷;そこの泉で Diana の沐浴をのぞき見した Actaeon が自らの猟犬どもに八つ裂きにされた》.</div>\r\n","<div class=\"hw\">Gargara</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ガルガラ《Troas の Ida 山の峰の一つ》.</div>\r\n","<div class=\"hw\">gargaridiō</div><div class=\"pos\">-āre, <i>intr</i></div><div class=\"def\">=<a href=\"entry://gargarizō\">gargarizo</a>.</div>\r\n","<div class=\"hw\">gargarisma</div><div class=\"pos\">-ātis, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘薬〙うがい薬.</div>\r\n","<div class=\"hw\">gargarismatium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">=<a href=\"entry://gargarisma\">gargarisma</a>.</div>\r\n","<div class=\"hw\">gargarizō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i>, <i>tr</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">うがいする.</div>\r\n","<div class=\"hw\">Gargilius</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"def\">ガルギリウス《ローマ人の氏族名;特に <i>Q</i>. ～ <i>Martialis</i>, 3世紀のローマの著述家》.</div>\r\n","<div class=\"hw\">Gargānus<SUP>1</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ガルガーヌス《Apulia の山;現 Monte Gargano》.</div><hr><div class=\"hw\">Gargānus<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Garganus 山の.</div>\r\n","<div class=\"hw\">Gargēttius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">(Attica の一市区)Gargettus の人(=哲学者 Epicurus).</div>\r\n","<div class=\"hw\">garriō</div><div class=\"pos\">-īre -īvī [-iī] -ītum, <i>intr</i>, <i>tr</i></div><div class=\"def\">ペチャクチャしゃべる, おしゃべりする.</div>\r\n","<div class=\"hw\">garrulitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://garrulus\">garrulus</a>]</div><div class=\"def\">(くどい)おしゃべり, 饒舌, 多弁.</div>\r\n","<div class=\"hw\">garrulus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[garrio]</div><div class=\"def\"><num>①</num> おしゃべりの, 饒舌な.</div><div class=\"def\"><num>②</num> 騒々しい;ざわめく.</div>\r\n","<div class=\"hw\">garrītus</div><div class=\"pos\">-ūs, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[↑<a href=\"entry://garriō\">garriō</a>]</div><div class=\"def\">おしゃべり.</div>\r\n","<div class=\"hw\">garum, -on</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">魚のソース.</div>\r\n","<div class=\"hw\">Garumna</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">ガルムナ《Gallia 南部の大河;現 Garonne》.</div>\r\n","<div class=\"hw\">Garumnī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ガルムニー《Aquitania の Garumna 河畔にいた一部族》.</div>\r\n","<div class=\"hw\">gastricus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://gastēr\">gastēr</a>]</div><div class=\"def\">〘解〙胃の.</div>\r\n","<div class=\"hw\">gastrimargia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[gaster]</div><div class=\"def\">大食, 貪食.</div>\r\n","<div class=\"hw\">gastrocōlicus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">〘解〙胃結腸の.</div>\r\n","<div class=\"hw\">gastrodynia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">胃痛.</div>\r\n","<div class=\"hw\">gastroepiploicus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">〘解〙胃大網の.</div>\r\n","<div class=\"hw\">gastronomia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">美食学;料理法.</div>\r\n","<div class=\"hw\">gastrotomia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘医〙胃切開(術).</div>\r\n","<div class=\"hw\">gastrītis</div><div class=\"pos\">-īdis, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘病〙胃炎.</div>\r\n","<div class=\"hw\">gastrūla</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘生物〙原腸胚.</div>\r\n","<div class=\"hw\">gastēr</div><div class=\"pos\">-teris [-trī], <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 腹.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘解〙胃.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘昆〙膨腹部.</div>\r\n","<div class=\"hw\">Gatēs</div><div class=\"pos\">-um, <i>m pl</i></div><div class=\"def\">ガテース《Aquitania にいた一部族》.</div>\r\n","<div class=\"hw\">gaudenter</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://gaudeō\">gaudeō</a>]</div><div class=\"def\">喜んで.</div>\r\n","<div class=\"hw\">gaudeō</div><div class=\"pos\">-ēre gāvīsus sum, <i>intr</i>, <i>tr</i></div><div class=\"def\">喜ぶ, 楽しむ 〈re;quod;+<i>acc c.inf</i>;+<i>inf</i>〉</div><div class=\"ex\"><i>delicto dolere, correctione gaudere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">間違いを悲しみ, 正されることを喜ぶ</span></div><div class=\"ex\"><i>quae perfecta esse</i> ～ (<author>C<small>IC</small></author>)<span class=\"ext\">私はそれらが成就されたことを喜ぶ.</span></div>\r\n","<div class=\"hw\">gaudium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[gaudeo]</div><div class=\"def\">喜び, 楽しみ.</div>\r\n","<div class=\"hw\">gaudiōsus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://gaudium\">gaudium</a>]</div><div class=\"def\">喜ばしい.</div>\r\n","<div class=\"hw\">Gaugamēla</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ガウガメーラ《Assyria の村;ここで Alexander 大王がペルシアの Dareus 3世を破った(前331)》.</div>\r\n","<div class=\"hw\">gaulus<SUP>1</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 手桶, バケツ.</div><div class=\"def\"><num>②</num> 商船.</div><hr><div class=\"hw\">gaulus<SUP>2</SUP></div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"def\">〘鳥〙=<a href=\"entry://merops\">merops</a>.</div>\r\n","<div class=\"hw\">Gaurus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ガウルス《Campania の山;ぶどう酒で有名》.</div>\r\n","<div class=\"hw\">gausape</div><div class=\"pos\">-is, <i>n</i>, <B>-um</B> -ī, <i>n</i>, <B>-ēs</B> -is, <i>m</i>, <B>-a</B> -ae, <i>f</i></div><div class=\"def\"><num>①</num> 粗紡毛織物, ラシャ.</div><div class=\"def\"><num>②</num> (もじゃもじゃの)ひげ.</div>\r\n","<div class=\"hw\">gavia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">〘鳥〙カモメ.</div>\r\n","<div class=\"hw\">gaza</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i><<i>Pers</i>.]</div><div class=\"def\"><num>①</num> (ペルシア王室の)宝物.</div><div class=\"def\"><num>②</num> 富, 財産.</div>\r\n","<div class=\"hw\">Gaza</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ガザ《Palaestina 南西部の港町》.</div>\r\n","<div class=\"hw\">gazophylacium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">宝物蔵.</div>\r\n","<div class=\"hw\">Gebenna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">=<a href=\"entry://Cebenna\">Cebenna</a>.</div>\r\n","<div class=\"hw\">Gedrōsia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ゲドローシア(ー)《Carmania と India の間のアラビア海沿岸地方;現 Makran》.</div>\r\n","<div class=\"hw\">Gedrōsī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">Gedrosia の住民.</div>\r\n","<div class=\"hw\">gehenna</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i><<i>Heb</i>.]</div><div class=\"def\">〘聖〙地獄, 焦熱地獄.</div>\r\n","<div class=\"hw\">gehennālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://gehenna\">gehenna</a>]</div><div class=\"def\">地獄の.</div>\r\n","<div class=\"hw\">Geidumnī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ゲイドゥムニー《Gallia の Nervii 族支配下の部族》.</div>\r\n","<div class=\"hw\">Gela</div><div class=\"pos\">-ae, <i>f</i>, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ゲラ(ー)《 (1)(<i>f</i>)Sicilia 島南岸の町. (2)(<i>m</i>)Sicilia 島南岸の川》.</div>\r\n","<div class=\"hw\">gelascō</div><div class=\"pos\">-ere, <i>intr inch</i></div><div class=\"ori\">[gelo]</div><div class=\"def\">凍る.</div>\r\n","<div class=\"hw\">gelasīnus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">えくぼ.</div>\r\n","<div class=\"hw\">Gelduba</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ゲルドゥバ《Gallia Belgica にあった Ubii 族の城砦》.</div>\r\n","<div class=\"hw\">gelefactus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[gelu/fio]</div><div class=\"def\">凍った.</div>\r\n","<div class=\"hw\">Gelensēs</div><div class=\"pos\">-ium, <i>m pl</i></div><div class=\"def\">Gela (1) の住民.</div>\r\n","<div class=\"hw\">gelida</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[gelidus]</div><div class=\"def\">(<i>sc. </i> aqua)氷のように冷たい水.</div>\r\n","<div class=\"hw\">gelidus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[gelu]</div><div class=\"def\"><num>①</num> 氷の;氷のような, 冷たい.</div><div class=\"def\"><num>②</num> (死んで・恐怖で)冷たくなった, 硬直した.</div>\r\n","<div class=\"hw\">gelidē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://gelidus\">gelidus</a>]</div><div class=\"def\">冷淡に, 熱意なく.</div>\r\n","<div class=\"hw\">Gellius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ゲッリウス《ローマ人の氏族名;特に <i>Aulus</i> ～, 2世紀の文法家;<i>Noctes Atticae</i> 「アッティカ夜話」 の著者》.</div>\r\n","<div class=\"hw\">Gelās</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">=<a href=\"entry://Gela\">Gela (2)</a> .</div>\r\n","<div class=\"hw\">gelātina</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">ゼラチン.</div>\r\n","<div class=\"hw\">gelātinōsus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">ゼラチン状の, 膠状の.</div>\r\n","<div class=\"hw\">gelātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[gelo]</div><div class=\"def\">凍結, 氷結.</div>\r\n","<div class=\"hw\">gelō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i>, <i>intr</i></div><div class=\"ori\">[gelu]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>tr</i>)</div><div class=\"def\"><num>①</num> 凍らせる, 氷結させる.</div><div class=\"def\"><num>②</num> ぞっとさせる, 硬直させる.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>intr</i>)凍る.</div>\r\n","<div class=\"hw\">Gelō(n)</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ゲロー(ン)《Syracusae の王(前3世紀);Hiero II の息子》.</div>\r\n","<div class=\"hw\">Gelōnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Geloni 族の.</div>\r\n","<div class=\"hw\">Gelōnī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ゲローニー, <SUP>*</SUP>-ノイ《Borysthenes 河畔にいた Scythae 人の一部族》.</div>\r\n","<div class=\"hw\">Gelōus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Gela (1) の.</div>\r\n","<div class=\"hw\">gelū</div><div class=\"pos\">-ūs, <i>n</i>, <B>gelum</B> -ī, <i>n</i>, <B>gelus</B> -ūs, <i>m</i></div><div class=\"def\"><num>①</num> 寒気, 寒冷.</div><div class=\"def\"><num>②</num> (老齢・死・恐怖などで)冷えること.</div>\r\n","<div class=\"hw\">gemebundus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[gemo]</div><div class=\"def\">うめいている, ため息をついている.</div>\r\n","<div class=\"hw\">gemellipara</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://gemellus\">gemellus<SUP>1</SUP></a>/pario<SUP>2</SUP>]</div><div class=\"def\">双生児の母(=<a href=\"entry://Lātōna\">Latona</a>).</div>\r\n","<div class=\"hw\">gemellus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://geminus\">geminus<SUP>1</SUP></a>.</div><hr><div class=\"hw\">gemellus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> ふたご.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘解〙双子筋.</div>\r\n","<div class=\"hw\">gemibilis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[gemo]</div><div class=\"def\">嘆かわしい.</div>\r\n","<div class=\"hw\">Geminius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ゲミニウス《ローマ人の氏族名》.</div>\r\n","<div class=\"hw\">geminus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> ふたごの, 双生の.</div><div class=\"def\"><num>②</num> 二重の, 一対の.</div><div class=\"def\"><num>③</num> 似ている, 同様の.</div><hr><div class=\"hw\">geminus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> ふたごの一人.</div><div class=\"def\"><num>②</num> (<i>pl</i> Gemini)〘天〙双子座;〘占星〙双子宮《Castor と Pollux》.</div>\r\n","<div class=\"hw\">Geminus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ゲミヌス《Servilia 氏族に属する家名》.</div>\r\n","<div class=\"hw\">geminātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[gemino]</div><div class=\"def\">重複, 反復.</div>\r\n","<div class=\"hw\">geminē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[geminus<SUP>1</SUP>]</div><div class=\"def\">二重に.</div>\r\n","<div class=\"hw\">geminō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i>, <i>intr</i></div><div class=\"ori\">[↓<a href=\"entry://geminus\">geminus<SUP>1</SUP></a>]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>tr</i>)</div><div class=\"def\"><num>①</num> 倍にする.</div><div class=\"def\"><num>②</num> 組み合わせる, 結合する.</div><div class=\"def\"><num>③</num> 繰り返す, 反復する.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>intr</i>)2倍である.</div>\r\n","<div class=\"hw\">gemitus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://gemō\">gemo</a>.</div><hr><div class=\"hw\">gemitus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> 嘆息, うめき.</div><div class=\"def\"><num>②</num> うなり, とどろき.</div><div class=\"def\"><num>③</num> 苦悩, 悲嘆.</div>\r\n","<div class=\"hw\">gemma</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 芽, つぼみ.</div><div class=\"def\"><num>②</num> 宝石.</div><div class=\"def\"><num>③</num> 宝石をちりばめた杯.</div><div class=\"def\"><num>④</num> 印章付き指輪, 印.</div><div class=\"def\"><num>⑤</num> (クジャクの尾の)羽紋.</div><div class=\"def\"><num>⑥</num> <SUP>◇</SUP>〘植〙無性芽.</div>\r\n","<div class=\"hw\">gemmans</div><div class=\"pos\">-antis, <i>adj</i>(<i>prp</i>)</div><div class=\"ori\">[gemmo]</div><div class=\"def\"><num>①</num> 宝石をちりばめた.</div><div class=\"def\"><num>②</num> 装飾を施された;宝石のような.</div>\r\n","<div class=\"hw\">gemmascō</div><div class=\"pos\">-ere, <i>intr inch</i></div><div class=\"ori\">[gemmo]</div><div class=\"def\">芽ぐむ.</div>\r\n","<div class=\"hw\">gemmeus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[gemma]</div><div class=\"def\"><num>①</num> 宝石をちりばめた.</div><div class=\"def\"><num>②</num> 宝石のような;輝いている.</div>\r\n","<div class=\"hw\">gemmifer</div><div class=\"pos\">-fera -ferum, <i>adj</i></div><div class=\"ori\">[gemma/fero]</div><div class=\"def\">宝石を含んでいる, 宝石を産する.</div>\r\n","<div class=\"hw\">gemmula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[gemma]</div><div class=\"def\"><num>①</num> 小さな芽.</div><div class=\"def\"><num>②</num> 小さな宝石.</div>\r\n","<div class=\"hw\">gemmārius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[gemma]</div><div class=\"def\">宝石商.</div>\r\n","<div class=\"hw\">gemmātus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[gemmo]</div><div class=\"def\">宝石をちりばめた.</div>\r\n","<div class=\"hw\">gemmō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i></div><div class=\"ori\">[gemma]</div><div class=\"def\"><num>①</num> 発芽する, 芽ぐむ.</div><div class=\"def\"><num>②</num> 宝石をちりばめられている;輝いている.</div>\r\n","<div class=\"hw\">gemursa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">足指に生ずるタコ.</div>\r\n","<div class=\"hw\">gemuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://gemō\">gemo</a>.</div>\r\n","<div class=\"hw\">gemō</div><div class=\"pos\">-ere gemuī gemitum, <i>intr</i>, <i>tr</i></div><div class=\"def\"><num0>Ⅰ</num0> (<i>intr</i>)</div><div class=\"def\"><num>①</num> うめく, 嘆息する.</div><div class=\"def\"><num>②</num> (ライオンが)ほえる, (ハトが)クークー鳴く.</div><div class=\"def\"><num>③</num> うなるような音を出す, ギーギー鳴る.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>tr</i>)嘆く, 悲嘆する 〈alqd〉.</div>\r\n","<div class=\"hw\">Gemōniae (scālae)</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"def\">Aventinus 丘から Tiberis 川に通ずる階段《 「嘆きの階段」 の意;処刑された犯罪者の死体はここを引きずり下ろされ, 川へ投じられた》.</div>\r\n","<div class=\"hw\">gena</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> ほお.</div><div class=\"def\"><num>②</num> まぶた.</div><div class=\"def\"><num>③</num> (<i>pl</i>)眼;眼窩.</div>\r\n","<div class=\"hw\">Genaunī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ゲナウニー《Raetia にいたゲルマン系一部族》.</div>\r\n","<div class=\"hw\">gener</div><div class=\"pos\">-erī, <i>m</i></div><div class=\"ori\">[geno, gigno]</div><div class=\"def\"><num>①</num> 婿.</div><div class=\"def\"><num>②</num> 将来の婿.</div><div class=\"def\"><num>③</num> 孫娘の夫.</div><div class=\"def\"><num>④</num> 義兄弟.</div>\r\n","<div class=\"hw\">generascō</div><div class=\"pos\">-ere, <i>intr inch</i></div><div class=\"ori\">[genero]</div><div class=\"def\">生まれる, 生ずる, 発生する.</div>\r\n","<div class=\"hw\">generābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[genero]</div><div class=\"def\">発生させることができる, 創造力のある.</div>\r\n","<div class=\"hw\">generālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[genus]</div><div class=\"def\"><num>①</num> 種の, 種に共通の.</div><div class=\"def\"><num>②</num> 一般的な, 普遍的な.</div>\r\n","<div class=\"hw\">generāliter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[generalis]</div><div class=\"def\">一般に.</div>\r\n","<div class=\"hw\">generālitās</div><div class=\"pos\">-ātis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↑<a href=\"entry://generālis\">generālis</a>]</div><div class=\"def\">一般性, 普遍性.</div>\r\n","<div class=\"hw\">generātim</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[genus]</div><div class=\"def\"><num>①</num> 種類[階級]によって.</div><div class=\"def\"><num>②</num> 一般に.</div>\r\n","<div class=\"hw\">generātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[genero]</div><div class=\"def\"><num>①</num> 子を産むこと, 生殖.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>(世)代.</div>\r\n","<div class=\"hw\">generātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[genero]</div><div class=\"def\">生みの親, 父親.</div>\r\n","<div class=\"hw\">generātrix</div><div class=\"pos\">-īcis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://generō\">generō</a>]</div><div class=\"def\">産み出す人《女性》.</div>\r\n","<div class=\"hw\">generātōrium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[↓<a href=\"entry://generātōrius\">generātōrius</a>]</div><div class=\"def\">生産手段.</div>\r\n","<div class=\"hw\">generātōrius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[generator]</div><div class=\"def\">生産に関する.</div>\r\n","<div class=\"hw\">generō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[genus]</div><div class=\"def\">生む, 生ずる.</div>\r\n","<div class=\"hw\">generōsitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://generōsus\">generōsus</a>]</div><div class=\"def\">高貴な生まれ, 血統のよいこと.</div>\r\n","<div class=\"hw\">generōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[genus<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 高貴な生まれの, 血統のよい.</div><div class=\"def\"><num>②</num> 寛大な;高潔な.</div>\r\n","<div class=\"hw\">generōsē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[generosus]</div><div class=\"def\">気高く.</div>\r\n","<div class=\"hw\">genesis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 発生, 誕生.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘聖〙創世記.</div><div class=\"def\"><num>③</num> 〘占星〙誕生時の星位.</div>\r\n","<div class=\"hw\">genesta</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">=<a href=\"entry://genista\">genista</a>.</div>\r\n","<div class=\"hw\">genesālia</div><div class=\"pos\">-ium, <SUP>◇</SUP><i>n pl</i></div><div class=\"ori\">[↓<a href=\"entry://genesis\">genesis</a>]</div><div class=\"def\">誕生の祝典.</div>\r\n","<div class=\"hw\">genethliacus<SUP>1</SUP></div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘占星〙誕生時の.</div><hr><div class=\"hw\">genethliacus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">占星師.</div>\r\n","<div class=\"hw\">genethlialogia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">占星術.</div>\r\n","<div class=\"hw\">genetrix</div><div class=\"pos\">-īcis, <i>f</i></div><div class=\"ori\">[genitor]</div><div class=\"def\">生む人, 母親</div><div class=\"ex\"><i>Aeneadum</i>(Aeneades の <i>pl gen</i>)～ (<author>L<small>UCR</small></author>)<span class=\"ext\">=<a href=\"entry://Venus\">Venus</a></span></div><div class=\"ex\"><i>magna deum</i> ～ (<author>V<small>ERG</small></author>)<span class=\"ext\">=<a href=\"entry://Cybelē\">Cybele</a>.</span></div>\r\n","<div class=\"hw\">genetīvus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[gigno]</div><div class=\"def\"><num>①</num> 誕生の;生来の.</div><div class=\"def\"><num>②</num> 〘文〙属格の</div><div class=\"ex\"><i>casus ～</i> (<author>S<small>UET</small></author>)<span class=\"ext\">属格.</span></div>\r\n","<div class=\"hw\">geneālogia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">系図, 系譜;系図学.</div>\r\n","<div class=\"hw\">geneālogus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">系図学者.</div>\r\n","<div class=\"hw\">geniculum</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[genu]</div><div class=\"def\"><num>①</num> (小さな)ひざ.</div><div class=\"def\"><num>②</num> (木の)節<SUB>ふし</SUB>, こぶ.</div>\r\n","<div class=\"hw\">geniculātim</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://geniculātus\">geniculātus</a>]</div><div class=\"def\">節<SUB>ふし</SUB>[こぶ]ごとに.</div>\r\n","<div class=\"hw\">geniculātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[geniculum]</div><div class=\"def\">節<SUB>ふし</SUB>[こぶ]のある.</div>\r\n","<div class=\"hw\">Geniculātus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[geniculum]</div><div class=\"def\">〘天〙(「ひざまずく人」 の意)ヘルクレス座(=<a href=\"entry://Engonasi(n)\">Engonasin</a>).</div>\r\n","<div class=\"hw\">geniculō</div><div class=\"pos\">-āre -āvī -ātum, <SUP>◇</SUP><i>intr</i></div><div class=\"ori\">[genu]</div><div class=\"def\">ひざを曲げる, ひざまずく.</div>\r\n","<div class=\"hw\">genimen</div><div class=\"pos\">-minis, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[gigno]</div><div class=\"def\"><num>①</num> 産物, 果実.</div><div class=\"def\"><num>②</num> 子孫.</div>\r\n","<div class=\"hw\">genista</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">〘植〙エニシダ.</div>\r\n","<div class=\"hw\">genitofemorālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">〘解〙陰部大腿の.</div>\r\n","<div class=\"hw\">genitor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[gigno]</div><div class=\"def\"><num>①</num> 生みの親, 父親.</div><div class=\"def\"><num>②</num> 創造者.</div><div class=\"def\"><num>③</num> 創建[創始]者.</div>\r\n","<div class=\"hw\">genitrix</div><div class=\"pos\">-īcis, <i>f</i></div><div class=\"def\">=<a href=\"entry://genetrix\">genetrix</a>.</div>\r\n","<div class=\"hw\">genitus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://gignō\">gigno</a>.</div><hr><div class=\"hw\">genitus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\">生殖, 出産.</div>\r\n","<div class=\"hw\">genitābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[gigno]</div><div class=\"def\">生産力のある, 多産の.</div>\r\n","<div class=\"hw\">genitāle</div><div class=\"pos\">-is, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://genitālis\">genitālis</a>]</div><div class=\"def\">(<i>sc. </i> membrum)生殖器.</div>\r\n","<div class=\"hw\">genitālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[gigno]</div><div class=\"def\"><num>①</num> 生殖の, 誕生の.</div><div class=\"def\"><num>②</num> 多産の.</div>\r\n","<div class=\"hw\">Genitālis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://genitālis\">genitālis</a>]</div><div class=\"def\">〘神話〙出産の女神としての Diana の添え名.</div>\r\n","<div class=\"hw\">genitūra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[gigno]</div><div class=\"def\"><num>①</num> 生殖, 出産.</div><div class=\"def\"><num>②</num> 精液.</div><div class=\"def\"><num>③</num> 〘占星〙誕生時の星位.</div>\r\n","<div class=\"hw\">genitūrus</div><div class=\"pos\">-a -um, <i>fut p</i></div><div class=\"def\">⇒<a href=\"entry://gignō\">gigno</a>.</div>\r\n","<div class=\"hw\">genius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[gigno]</div><div class=\"def\"><num>①</num> 守護神[霊].</div><div class=\"def\"><num>②</num> 才, 天分.</div><div class=\"def\"><num>③</num> 趣味, 嗜好.</div>\r\n","<div class=\"hw\">geniālia</div><div class=\"pos\">-ium, <SUP>◇</SUP><i>n pl</i></div><div class=\"ori\">[↓<a href=\"entry://geniālis\">geniālis</a>]</div><div class=\"def\">婚姻の床;結婚.</div>\r\n","<div class=\"hw\">geniālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[genius]</div><div class=\"def\"><num>①</num> 結婚の.</div><div class=\"def\"><num>②</num> 楽しい, 愉快な;祝祭の, 祝宴の.</div>\r\n","<div class=\"hw\">geniāliter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://geniālis\">geniālis</a>]</div><div class=\"def\">楽しく, 愉快に.</div>\r\n","<div class=\"hw\">geniātus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[genius]</div><div class=\"def\">愉快な, 楽しい.</div>\r\n","<div class=\"hw\">gens</div><div class=\"pos\">gentis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://genō\">genō</a>]</div><div class=\"def\"><num>①</num> 氏族《同一の祖先・氏族名を有する数家族の集団》.</div><div class=\"def\"><num>②</num> 全世界</div><div class=\"ex\"><i>ubi gentium</i>? (<author>P<small>LAUT</small></author>)<span class=\"ext\">いったいどこで</span></div><div class=\"ex\"><i>minime gentium</i> (<author>T<small>ER</small></author>)<span class=\"ext\">とんでもない.</span></div><div class=\"def\"><num>③</num> 種類.</div><div class=\"def\"><num>④</num> 血統;子孫.</div><div class=\"def\"><num>⑤</num> 民族, 国民.</div><div class=\"def\"><num>⑥</num> 地域, 国土.</div><div class=\"def\"><num>⑦</num> (<i>pl</i>)外国;外国人.</div>\r\n","<div class=\"hw\">genticus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://gens\">gens</a>]</div><div class=\"def\">国民[民族]の.</div>\r\n","<div class=\"hw\">gentīlicius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://gentīlis\">gentīlis<SUP>1</SUP></a>]</div><div class=\"def\"><num>①</num> (ある)氏族に属する.</div><div class=\"def\"><num>②</num> 民族の.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 異教の.</div>\r\n","<div class=\"hw\">gentīlis<SUP>1</SUP></div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[gens]</div><div class=\"def\"><num>①</num> 同氏族の.</div><div class=\"def\"><num>②</num> 同一国民[民族]の.</div><div class=\"def\"><num>③</num> 外国人の.</div><hr><div class=\"hw\">gentīlis<SUP>2</SUP></div><div class=\"pos\">-is, <i>m</i></div><div class=\"def\"><num>①</num> 同氏族の人;同国人.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 外国人;異教徒.</div>\r\n","<div class=\"hw\">gentīlitus</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[gentilis<SUP>1</SUP>]</div><div class=\"def\">国の風習によって.</div>\r\n","<div class=\"hw\">gentīlitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://gentīlis\">gentīlis<SUP>2</SUP></a>]</div><div class=\"def\"><num>①</num> 同氏族であること.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 異教.</div>\r\n","<div class=\"hw\">Genua</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ゲヌア《Liguria の港町;現 Genova》.</div>\r\n","<div class=\"hw\">genuflectō</div><div class=\"pos\">-ere -flexī -flexum, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[genu/flecto]</div><div class=\"def\">ひざまずく.</div>\r\n","<div class=\"hw\">genuflexus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://genuflectō\">genuflecto</a>.</div>\r\n","<div class=\"hw\">genuflexī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://genuflectō\">genuflecto</a>.</div>\r\n","<div class=\"hw\">genus</div><div class=\"pos\">-neris, <i>n</i></div><div class=\"def\"><num>①</num> 出自, 血統, 家系.</div><div class=\"def\"><num>②</num> 高貴な生まれ.</div><div class=\"def\"><num>③</num> 民族, 国民.</div><div class=\"def\"><num>④</num> 子孫.</div><div class=\"def\"><num>⑤</num> 種類, 種族.</div><div class=\"def\"><num>⑥</num> 性.</div><div class=\"def\"><num>⑦</num> 〘文〙性;態;法.</div><div class=\"def\"><num>⑧</num> 〘論〙類.</div><div class=\"def\"><num>⑨</num> 集団, 階級, 身分.</div><div class=\"def\"><num>⑩</num> 方法, 様式</div><div class=\"ex\">～ <i>vitae</i> (<author>C<small>IC</small></author>)<span class=\"ext\">生活様式, 暮らし方</span></div><div class=\"ex\">～ <i>dicendi</i> (<author>C<small>IC</small></author>)<span class=\"ext\">話し方, 文体, 語法.</span></div>\r\n","<div class=\"hw\">Genusus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ゲヌスス《Illyria の川》.</div>\r\n","<div class=\"hw\">genuālia</div><div class=\"pos\">-ium, <i>n pl</i></div><div class=\"ori\">[genu]</div><div class=\"def\">ひざ当て.</div>\r\n","<div class=\"hw\">genuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://gignō\">gigno</a>.</div>\r\n","<div class=\"hw\">genuīnitās</div><div class=\"pos\">-ātis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://genuīnus\">genuīnus<SUP>1</SUP></a>]</div><div class=\"def\">純正, 真正.</div>\r\n","<div class=\"hw\">genuīnus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[gigno]</div><div class=\"def\"><num>①</num> 生来の, 生得の.</div><div class=\"def\"><num>②</num> 本物の, 真正の.</div><hr><div class=\"hw\">genuīnus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[gena]</div><div class=\"def\">(<i>sc. </i> dens)奥歯, 臼歯.</div>\r\n","<div class=\"hw\">Genāva</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ゲナーウァ《Allobroges 族の町;現 Genève》.</div>\r\n","<div class=\"hw\">Genēva</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">=<a href=\"entry://Genāva\">Genava</a>.</div>\r\n","<div class=\"hw\">genīoglossus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">〘解〙頤<SUB>おとがい</SUB>舌筋の.</div>\r\n","<div class=\"hw\">genō</div><div class=\"pos\">-ere, <i>tr</i></div><div class=\"def\">《古形》=<a href=\"entry://gignō\">gigno</a>.</div>\r\n","<div class=\"hw\">genū</div><div class=\"pos\">-ūs, <i>n</i></div><div class=\"def\">ひざ.</div>\r\n","<div class=\"hw\">Genūcius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ゲヌーキウス《ローマ人の氏族名》.</div>\r\n","<div class=\"hw\">Georgica</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"ori\">[↓<a href=\"entry://georgicus\">georgicus</a>]</div><div class=\"def\">「農耕詩」《Vergilius の詩の題名》.</div>\r\n","<div class=\"hw\">georgicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">農耕の.</div>\r\n","<div class=\"hw\">Geraesticus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ゲラエスティクス, <SUP>*</SUP>ゲライスティコス《Ionia の Teos 近くの港》.</div>\r\n","<div class=\"hw\">Geraestus</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ゲラエストゥス, <SUP>*</SUP>ゲライストス《Euboea 島の南端の町と岬》.</div>\r\n","<div class=\"hw\">geranion</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙</div><div class=\"def\"><num>①</num> トリュフの一種.</div><div class=\"def\"><num>②</num> フウロソウ科の植物.</div>\r\n","<div class=\"hw\">gerdius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">織工.</div>\r\n","<div class=\"hw\">Gergovia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ゲルゴウィア《Gallia 中部にあった Arverni 族の町》.</div>\r\n","<div class=\"hw\">Germalus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ゲルマルス《Palatinus 丘北西部の窪地》.</div>\r\n","<div class=\"hw\">germen</div><div class=\"pos\">-minis, <i>n</i></div><div class=\"ori\">[gero]</div><div class=\"def\"><num>①</num> 芽, つぼみ.</div><div class=\"def\"><num>②</num> 芽ばえ, 起源.</div>\r\n","<div class=\"hw\">germinātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[germino]</div><div class=\"def\">発芽;芽, つぼみ.</div>\r\n","<div class=\"hw\">germinātus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[↓<a href=\"entry://germinō\">germinō</a>]</div><div class=\"def\">発芽.</div>\r\n","<div class=\"hw\">germinātīvus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[germen]</div><div class=\"def\">発芽させる.</div>\r\n","<div class=\"hw\">germinō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i></div><div class=\"ori\">[germen]</div><div class=\"def\">発芽する, 芽を出す.</div>\r\n","<div class=\"hw\">germāna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[germanus]</div><div class=\"def\">実の姉妹.</div>\r\n","<div class=\"hw\">Germānia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ゲルマーニア《Germani 族の地(ほぼ現在のドイツ)》.</div>\r\n","<div class=\"hw\">Germāniciānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://Germānicus\">Germānicus<SUP>1</SUP></a>]</div><div class=\"def\">Germania に駐屯している.</div>\r\n","<div class=\"hw\">Germānicus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Germania(人)の.</div><hr><div class=\"hw\">Germānicus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ゲルマーニクス《Germania で戦勝した数人のローマの将軍の添え名;特に ～ <i>Julius Caesar</i>, Tiberius 帝の甥で後に養子となる(前15‐後19);Claudius 帝の兄で Caligula 帝の父》.</div>\r\n","<div class=\"hw\">germānitus</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://germānus\">germānus<SUP>1</SUP></a>]</div><div class=\"def\">兄弟のように, 誠実に.</div>\r\n","<div class=\"hw\">germānitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[germanus]</div><div class=\"def\"><num>①</num> 兄弟[姉妹]関係.</div><div class=\"def\"><num>②</num> (植民市どうしが)母市を同じくすること.</div><div class=\"def\"><num>③</num> 類似.</div>\r\n","<div class=\"hw\">germānus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[germen]</div><div class=\"def\"><num>①</num> 父母を同じくする, 同じ両親の.</div><div class=\"def\"><num>②</num> 兄弟の, 姉妹の.</div><div class=\"def\"><num>③</num> 真実の, 正真正銘の.</div><hr><div class=\"hw\">germānus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">(同父母の)兄弟.</div>\r\n","<div class=\"hw\">Germānus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Germania(人)の.</div><hr><div class=\"hw\">Germānus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">Germania 人.</div>\r\n","<div class=\"hw\">germānē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[germanus<SUP>1</SUP>]</div><div class=\"def\">真実に, 誠実に.</div>\r\n","<div class=\"hw\">Germānī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ゲルマーニー, <SUP>∥</SUP>ゲルマン人.</div>\r\n","<div class=\"hw\">geronticōs</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">老人のように.</div>\r\n","<div class=\"hw\">gerontocomīum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">老人救貧院.</div>\r\n","<div class=\"hw\">gerontēa</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙ノボロギク(=<a href=\"entry://ērigerōn\">erigeron</a>, <a href=\"entry://seneciō\">senecio</a>).</div>\r\n","<div class=\"hw\">gerrae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 枝編み細工.</div><div class=\"def\"><num>②</num> (<i>int</i> として)くだらない! ばかばかしい!</div>\r\n","<div class=\"hw\">gerrō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"ori\">[↑<a href=\"entry://gerrae\">gerrae</a>]</div><div class=\"def\">(非難・軽蔑のことばとして)ぐうたら, 役立たず.</div>\r\n","<div class=\"hw\">gerula</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[gero]</div><div class=\"def\">運搬人《女性》.</div>\r\n","<div class=\"hw\">gerulifigulus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[↓<a href=\"entry://gerulus\">gerulus</a>/figulus]</div><div class=\"def\">一味, 共犯《喜劇の造語》.</div>\r\n","<div class=\"hw\">gerulus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[gero]</div><div class=\"def\">運搬人.</div>\r\n","<div class=\"hw\">gerundium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[gero]</div><div class=\"def\">〘文〙動詞的中性名詞, 動名詞.</div>\r\n","<div class=\"hw\">gerundīvum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[gero]</div><div class=\"def\">〘文〙動詞的形容詞, 動形容詞.</div>\r\n","<div class=\"hw\">gerō</div><div class=\"pos\">-ere gessī gestum, <i>tr</i></div><div class=\"def\"><num>①</num> 運ぶ, 運んで行く 〈alqd in locum〉.</div><div class=\"def\"><num>②</num> 持ち運ぶ, 携える;身に着けている.</div><div class=\"def\"><num>③</num> もつ, 示す</div><div class=\"ex\"><i>personam gerere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">役割を演ずる</span></div><div class=\"ex\"><i>se gerere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">ふるまう.</span></div><div class=\"def\"><num>④</num> (心に)いだく.</div><div class=\"def\"><num>⑤</num> 生み出す, 作り出す.</div><div class=\"def\"><num>⑥</num> 行なう, 処理する, 管理する</div><div class=\"ex\"><i>alqd bene</i> [<i>male</i>] <i>gerere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">あることをうまく[下手に]やる, 成功[失敗]する</span></div><div class=\"ex\"><i>res gestae</i> (<author>C<small>IC</small></author>)<span class=\"ext\">なされたこと, 業績, 手柄</span></div><div class=\"ex\"><i>alci morem gerere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">ある人の意向に合わせてふるまう.</span></div><div class=\"def\"><num>⑦</num> (時を)過ごす.</div>\r\n","<div class=\"hw\">Gerōnium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">ゲローニウム《Apulia の城砦》.</div>\r\n","<div class=\"hw\">gerūsia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> (Sparta の)長老会.</div><div class=\"def\"><num>②</num> (Sardes の)養老院.</div>\r\n","<div class=\"hw\">geseoreta</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">小舟の一種.</div>\r\n","<div class=\"hw\">Gesoriacus</div><div class=\"pos\">-ī, <i>m</i>, <B>-um</B> -ī, <i>n</i></div><div class=\"def\">ゲソリアクス《Gallia Belgica にあった Morini 族の港町;後名 Bononia;現 Boulogne-sur-Mer》.</div>\r\n","<div class=\"hw\">gessī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://gerō\">gero</a>.</div>\r\n","<div class=\"hw\">gesticulor</div><div class=\"pos\">-ārī -ātus sum, <i>intr</i>, <i>tr dep</i></div><div class=\"ori\">[↓<a href=\"entry://gesticulus\">gesticulus</a>]</div><div class=\"def\">身振りで表わす.</div>\r\n","<div class=\"hw\">gesticulus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m dim</i></div><div class=\"ori\">[gestus<SUP>2</SUP>]</div><div class=\"def\">笑劇(mimus)の所作;身振り.</div>\r\n","<div class=\"hw\">gesticulātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://gesticulor\">gesticulor</a>]</div><div class=\"def\"><num>①</num> 笑劇(mimus)の所作.</div><div class=\"def\"><num>②</num> 身振り, 動作.</div>\r\n","<div class=\"hw\">gestitō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr freq</i></div><div class=\"ori\">[↓<a href=\"entry://gestō\">gestō</a>]</div><div class=\"def\">常に[頻繁に]携えている.</div>\r\n","<div class=\"hw\">gestiō<SUP>1</SUP></div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[gero]</div><div class=\"def\"><num>①</num> 行動, ふるまい.</div><div class=\"def\"><num>②</num> 実行.</div><hr><div class=\"hw\">gestiō<SUP>2</SUP></div><div class=\"pos\">-īre -īvī [-iī] -ītum, <i>intr</i></div><div class=\"ori\">[gestus<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> 大喜びする, はめをはずす.</div><div class=\"def\"><num>②</num> (...したくて)むずむずする.</div><div class=\"def\"><num>③</num> 切望[熱望]する 〈+<i>inf</i>〉.</div>\r\n","<div class=\"hw\">gestor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[gero]</div><div class=\"def\"><num>①</num> 言いふらす人, 告げ口屋.</div><div class=\"def\"><num>②</num> 管理者, 遂行者.</div>\r\n","<div class=\"hw\">gestum</div><div class=\"pos\">-ī, <i>n</i>(<i>pp</i>)</div><div class=\"ori\">[gero]</div><div class=\"def\">なされたこと;(<i>pl</i>)功績, 偉業.</div>\r\n","<div class=\"hw\">gestus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://gerō\">gero</a>.</div><hr><div class=\"hw\">gestus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> 姿勢, 態度, ふるまい.</div><div class=\"def\"><num>②</num> 身振り.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 処理, 遂行.</div>\r\n","<div class=\"hw\">gestuōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[gestus<SUP>2</SUP>]</div><div class=\"def\">身振りの多い.</div>\r\n","<div class=\"hw\">gestābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[gesto]</div><div class=\"def\">持ち運びできる, 運搬できる.</div>\r\n","<div class=\"hw\">gestāmen</div><div class=\"pos\">-minis, <i>n</i></div><div class=\"ori\">[gesto]</div><div class=\"def\"><num>①</num> 運搬されるもの《荷物, 武具, 装身具など》.</div><div class=\"def\"><num>②</num> 運搬道具, 乗物《担架, 輿<SUB>こし</SUB>など》.</div>\r\n","<div class=\"hw\">gestātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[gesto]</div><div class=\"def\"><num>①</num> <SUP>◇</SUP> 運ぶこと, 運搬.</div><div class=\"def\"><num>②</num> (乗物で)運ばれること, (乗物に)乗ること.</div><div class=\"def\"><num>③</num> 遊歩道, 馬車道.</div>\r\n","<div class=\"hw\">gestātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[gesto]</div><div class=\"def\"><num>①</num> 運ぶ者.</div><div class=\"def\"><num>②</num> (馬に乗って)郊外へ出かける人.</div>\r\n","<div class=\"hw\">gestātus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[gesto]</div><div class=\"def\">運ぶこと, 運搬.</div>\r\n","<div class=\"hw\">gestātōrius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://gestātor\">gestātor</a>]</div><div class=\"def\">運ぶための.</div>\r\n","<div class=\"hw\">gestō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i>(<i>intr</i>)<i>freq</i></div><div class=\"ori\">[gero]</div><div class=\"def\"><num>①</num> 持ち運ぶ, 携える.</div><div class=\"def\"><num>②</num> (心に)いだく.</div><div class=\"def\"><num>③</num> (<i>pass</i>, <i>intr</i>)乗物で行く.</div>\r\n","<div class=\"hw\">Geta</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">ゲタ《ローマ人の家名》.</div>\r\n","<div class=\"hw\">Getae</div><div class=\"pos\">-ārum, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ゲタエ, <SUP>*</SUP>ゲタイ《Danubius 下流域にいた Thracia の一部族》.</div>\r\n","<div class=\"hw\">Geticus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Getae 族の;Thracia の.</div>\r\n","<div class=\"hw\">Geticē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://Geticus\">Geticus</a>]</div><div class=\"def\">Getae 族のように.</div>\r\n","<div class=\"hw\">geōdaesia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">土地の測量, 測地学.</div>\r\n","<div class=\"hw\">geōgraphia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">地理学.</div>\r\n","<div class=\"hw\">geōgraphicus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">地理学の.</div>\r\n","<div class=\"hw\">geōgraphus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">地理学者.</div>\r\n","<div class=\"hw\">geōmetria</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">幾何学.</div>\r\n","<div class=\"hw\">geōmetrica</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"ori\">[geometricus]</div><div class=\"def\">幾何学.</div>\r\n","<div class=\"hw\">geōmetricus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">幾何学の.</div>\r\n","<div class=\"hw\">geōmetricē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://geōmetricus\">geōmetricus</a>]</div><div class=\"def\">幾何学的に.</div>\r\n","<div class=\"hw\">geōmetrēs, -a</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">幾何学者.</div>\r\n","<div class=\"hw\">geōtaxis</div><div class=\"pos\">-is, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘生物〙走地性.</div>\r\n","<div class=\"hw\">gibba</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[gibbus]</div><div class=\"def\">(背の)こぶ.</div>\r\n","<div class=\"hw\">gibber<SUP>1</SUP></div><div class=\"pos\">-era -erum, <i>adj</i></div><div class=\"def\">せむしの.</div><hr><div class=\"hw\">gibber<SUP>2</SUP></div><div class=\"pos\">-eris, <i>m</i></div><div class=\"def\">(背の)こぶ.</div>\r\n","<div class=\"hw\">gibberōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://gibber\">gibber<SUP>2</SUP></a>]</div><div class=\"def\">せむしの.</div>\r\n","<div class=\"hw\">gibbus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">こぶのある.</div><hr><div class=\"hw\">gibbus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">こぶ.</div>\r\n","<div class=\"hw\">Gigantes</div><div class=\"pos\">-um, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘神話〙ギガンテス《Olympus の神々を襲おうと企てた巨人族;Juppiter その他の神々に退治された》.</div>\r\n","<div class=\"hw\">gigantomachia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘神話〙巨人族との戦い《Gigantes と Olympus の神々との戦い》.</div>\r\n","<div class=\"hw\">Gigantēus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">巨人族の.</div>\r\n","<div class=\"hw\">gignentia</div><div class=\"pos\">-ium, <i>n pl</i>(<i>prp</i>)</div><div class=\"ori\">[↓<a href=\"entry://gignō\">gignō</a>]</div><div class=\"def\">草木, 植物.</div>\r\n","<div class=\"hw\">gignō</div><div class=\"pos\">-ere genuī genitum, <i>tr</i></div><div class=\"ori\">[geno]</div><div class=\"def\"><num>①</num> 産む, 生ずる;(<i>pass</i>)生まれる.</div><div class=\"def\"><num>②</num> ひき起こす.</div>\r\n","<div class=\"hw\">Gigās</div><div class=\"pos\">-antis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">巨人族の一人.</div>\r\n","<div class=\"hw\">gilvus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">薄黄色の.</div>\r\n","<div class=\"hw\">ginglymus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘解〙蝶番<SUB>ちょうつがい</SUB>関節.</div>\r\n","<div class=\"hw\">gingīva</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">歯ぐき, 歯肉.</div>\r\n","<div class=\"hw\">glabellus</div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"ori\">[↓<a href=\"entry://glaber\">glaber<SUP>1</SUP></a>]</div><div class=\"def\">毛のない, つるつるの.</div>\r\n","<div class=\"hw\">glaber<SUP>1</SUP></div><div class=\"pos\">-bra -brum, <i>adj</i></div><div class=\"def\">毛のない, つるつるの.</div><hr><div class=\"hw\">glaber<SUP>2</SUP></div><div class=\"pos\">-brī, <i>m</i></div><div class=\"def\">ひげのない少年奴隷;稚児.</div>\r\n","<div class=\"hw\">glabrescō</div><div class=\"pos\">-ere, <i>intr inch</i></div><div class=\"ori\">[glaber<SUP>1</SUP>]</div><div class=\"def\">毛がなくなる, つるつるになる.</div>\r\n","<div class=\"hw\">Glabriō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\">グラブリオー《Acilia 氏族に属する家名》.</div>\r\n","<div class=\"hw\">glabrō</div><div class=\"pos\">-āre, <i>tr</i></div><div class=\"ori\">[glaber]</div><div class=\"def\">毛を抜く[取る].</div>\r\n","<div class=\"hw\">glaciālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://glaciēs\">glaciēs</a>]</div><div class=\"def\">氷の;氷のような.</div>\r\n","<div class=\"hw\">glaciēs</div><div class=\"pos\">-ēī, <i>f</i></div><div class=\"def\"><num>①</num> 氷.</div><div class=\"def\"><num>②</num> 硬さ.</div>\r\n","<div class=\"hw\">glaciō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i>, <i>intr</i></div><div class=\"ori\">[↑<a href=\"entry://glaciēs\">glaciēs</a>]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>tr</i>)凍らせる.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>intr</i>)固まる.</div>\r\n","<div class=\"hw\">gladiola</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘植〙=<a href=\"entry://gladiolus\">gladiolus 2</a>.</div>\r\n","<div class=\"hw\">gladiolus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[↓<a href=\"entry://gladius\">gladius</a>]</div><div class=\"def\"><num>①</num> 小さな剣.</div><div class=\"def\"><num>②</num> 〘植〙グラジオラス.</div>\r\n","<div class=\"hw\">gladius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 剣, 刀.</div><div class=\"def\"><num>②</num> 殺戮.</div><div class=\"def\"><num>③</num> 剣闘士の試合.</div>\r\n","<div class=\"hw\">gladiātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[gladius]</div><div class=\"def\"><num>①</num> 剣闘士.</div><div class=\"def\"><num>②</num> (<i>pl</i>)剣闘士の試合.</div>\r\n","<div class=\"hw\">gladiātōrium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://gladiātōrius\">gladiātōrius</a>]</div><div class=\"def\">剣闘士の給料.</div>\r\n","<div class=\"hw\">gladiātōrius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[gladiator]</div><div class=\"def\">剣闘士の.</div>\r\n","<div class=\"hw\">gladiātūra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[gladiator]</div><div class=\"def\">剣闘士の職.</div>\r\n","<div class=\"hw\">glaeba</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 土塊, 土くれ.</div><div class=\"def\"><num>②</num> 土壌;耕地.</div><div class=\"def\"><num>③</num> 塊り.</div>\r\n","<div class=\"hw\">glaebula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[glaeba]</div><div class=\"def\"><num>①</num> 小さな土くれ.</div><div class=\"def\"><num>②</num> 小さな耕地.</div><div class=\"def\"><num>③</num> 小さな塊り.</div>\r\n","<div class=\"hw\">glaebulentus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[glaeba]</div><div class=\"def\">土くれの.</div>\r\n","<div class=\"hw\">glaebārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://glaeba\">glaeba</a>]</div><div class=\"def\">土くれの.</div>\r\n","<div class=\"hw\">glaebōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[glaeba]</div><div class=\"def\">土くれの多い.</div>\r\n","<div class=\"hw\">glaesum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">琥珀<SUB>こはく</SUB>.</div>\r\n","<div class=\"hw\">glaesārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://glaesum\">glaesum</a>]</div><div class=\"def\">琥珀の.</div>\r\n","<div class=\"hw\">glandifer</div><div class=\"pos\">-fera -ferum, <i>adj</i></div><div class=\"ori\">[glans/fero]</div><div class=\"def\">どんぐりのなる.</div>\r\n","<div class=\"hw\">glandium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[glans]</div><div class=\"def\">(豚肉の)美味な部分.</div>\r\n","<div class=\"hw\">glandula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[↓<a href=\"entry://glans\">glans</a>]</div><div class=\"def\">〘解〙腺</div><div class=\"ex\"><SUP>◇</SUP>～ <i>thyreoidea</i><span class=\"ext\">甲状腺.</span></div>\r\n","<div class=\"hw\">glans</div><div class=\"pos\">glandis, <i>f</i></div><div class=\"def\"><num>①</num> どんぐり《カシワ・クヌギ・ブナなどの実》.</div><div class=\"def\"><num>②</num> 投石器で投げる鉛の玉.</div><div class=\"def\"><num>③</num> 〘解〙亀頭.</div>\r\n","<div class=\"hw\">glastum</div><div class=\"pos\">-i, <i>n</i></div><div class=\"def\">〘植〙ホソバタイセイ.</div>\r\n","<div class=\"hw\">glauceum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">=<a href=\"entry://glaucion\">glaucion</a>.</div>\r\n","<div class=\"hw\">Glaucia</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">グラウキア《Servilia 氏族に属する家名》.</div>\r\n","<div class=\"hw\">glaucion</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">〘植〙ケシ科ツノゲシ属の植物.</div>\r\n","<div class=\"hw\">glaucus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">青灰色の.</div>\r\n","<div class=\"hw\">Glaucus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙グラウクス, <SUP>*</SUP>-コス《 (1) Sisyphus の息子で Bellerophon の父;自分の馬に食われて死んだ.(2) Troja 戦争における Lycia 勢の将;ギリシアの勇将 Diomedes と戦場でよろいを交換した.(3) 海神となった Boeotia の Anthedon の漁師》.</div>\r\n","<div class=\"hw\">glaucōma</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘病〙白内障.</div>\r\n","<div class=\"hw\">gleucinus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ぶどう液から作った.</div>\r\n","<div class=\"hw\">gliscō</div><div class=\"pos\">-ere, <i>intr</i></div><div class=\"def\">増大する, 膨張する, 広がる</div><div class=\"ex\"><i>gliscente in dies seditione</i> (<author>L<small>IV</small></author>)<span class=\"ext\">暴動が日に日に広がって.</span></div>\r\n","<div class=\"hw\">globulus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[↓<a href=\"entry://globus\">globus</a>]</div><div class=\"def\">小球;塊り.</div>\r\n","<div class=\"hw\">globus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 球, 球体.</div><div class=\"def\"><num>②</num> 塊り.</div><div class=\"def\"><num>③</num> 群集, 群れ.</div>\r\n","<div class=\"hw\">globātim</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[globus]</div><div class=\"def\">群れをなして.</div>\r\n","<div class=\"hw\">globō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[globus]</div><div class=\"def\"><num>①</num> 丸くする.</div><div class=\"def\"><num>②</num> 群がらせる.</div>\r\n","<div class=\"hw\">globōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[globus]</div><div class=\"def\">球形の, 丸い.</div>\r\n","<div class=\"hw\">glomerulus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m dim</i></div><div class=\"ori\">[glomus]</div><div class=\"def\"><num>①</num> 〘解〙糸球体.</div><div class=\"def\"><num>②</num> 〘植〙団散花序.</div>\r\n","<div class=\"hw\">glomerāmen</div><div class=\"pos\">-minis, <i>n</i></div><div class=\"ori\">[glomero]</div><div class=\"def\">丸めること;球, 球体.</div>\r\n","<div class=\"hw\">glomerātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://glomerō\">glomerō</a>]</div><div class=\"def\">(馬の)側対歩.</div>\r\n","<div class=\"hw\">glomerō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[glomus]</div><div class=\"def\"><num>①</num> 丸くする.</div><div class=\"def\"><num>②</num> 集める, 塊りにする.</div>\r\n","<div class=\"hw\">glomerōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[glomus]</div><div class=\"def\">球形の.</div>\r\n","<div class=\"hw\">glomiformis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://glomus\">glomus</a>/forma]</div><div class=\"def\">〘解〙糸球状の.</div>\r\n","<div class=\"hw\">glomus</div><div class=\"pos\">-meris, <i>n</i></div><div class=\"def\"><num>①</num> 糸玉, 糸まり.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘解〙糸球, グロムス</div><div class=\"ex\">～ <i>chorioideum</i><span class=\"ext\">脈絡糸球</span></div><div class=\"ex\">～ <i>coccygeum</i><span class=\"ext\">尾骨糸球.</span></div>\r\n","<div class=\"hw\">glossa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> <SUP>◇</SUP>(説明を要する)難語彙.</div><div class=\"def\"><num>②</num> (<i>pl</i>)難語集.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘昆〙中舌.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP>〘解〙舌.</div>\r\n","<div class=\"hw\">glossopalātīnus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">〘解〙口蓋舌の.</div>\r\n","<div class=\"hw\">glossārium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">説明を要する語彙.</div>\r\n","<div class=\"hw\">glossēma</div><div class=\"pos\">-atis, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(説明を要する)難語彙.</div>\r\n","<div class=\"hw\">glossēmaticus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">廃語の, 外来語の.</div>\r\n","<div class=\"hw\">glottis</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 〘鳥〙ウズラ.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘解〙声門.</div>\r\n","<div class=\"hw\">glucōsum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘化〙ブドウ糖.</div>\r\n","<div class=\"hw\">Glycera</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">グリュケラ(ー)《ギリシア人の女性名; (1) Athenae の有名な娼婦で Menander の愛人.(2) Horatius の愛人.(3) Tibullus の愛人》.</div>\r\n","<div class=\"hw\">glycerinum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘化〙グリセリン.</div>\r\n","<div class=\"hw\">glycysis</div><div class=\"pos\">-idis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">=<a href=\"entry://glycysīdē\">glycyside</a>.</div>\r\n","<div class=\"hw\">glycysīdē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙ボタン, シャクヤク.</div>\r\n","<div class=\"hw\">Glycōn</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">グリュコーン《Horatius と同時代の有名な格闘家》.</div>\r\n","<div class=\"hw\">glārea</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">砂利.</div>\r\n","<div class=\"hw\">glāreōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://glārea\">glārea</a>]</div><div class=\"def\">砂利の多い.</div>\r\n","<div class=\"hw\">glēb-</div><div class=\"def\">⇒glaeb-.</div>\r\n","<div class=\"hw\">glēchōn</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙メグサハッカ.</div>\r\n","<div class=\"hw\">glēsum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">=<a href=\"entry://glaesum\">glaesum</a>.</div>\r\n","<div class=\"hw\">glīs</div><div class=\"pos\">glīris, <i>m</i></div><div class=\"def\">〘動〙ヤマネ(山鼠).</div>\r\n","<div class=\"hw\">glōria</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 名声, 評判.</div><div class=\"def\"><num>②</num> 栄誉, 誉れ.</div><div class=\"def\"><num>③</num> 功業.</div><div class=\"def\"><num>④</num> 名誉欲, 虚栄心.</div><div class=\"def\"><num>⑤</num> 誇り, 自尊心.</div>\r\n","<div class=\"hw\">glōrianter</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[glorior]</div><div class=\"def\">得意になって.</div>\r\n","<div class=\"hw\">glōrificus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[gloria/facio]</div><div class=\"def\">栄光に満ちた.</div>\r\n","<div class=\"hw\">glōrificātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://glōrificō\">glōrificō</a>]</div><div class=\"def\">賛美, (神の)栄光をたたえること.</div>\r\n","<div class=\"hw\">glōrificō</div><div class=\"pos\">-āre -āvī -ātum, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://glōrificus\">glōrificus</a>]</div><div class=\"def\">賛美する, (神の)栄光をたたえる.</div>\r\n","<div class=\"hw\">glōriola</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[gloria]</div><div class=\"def\">ささいな栄誉[名声].</div>\r\n","<div class=\"hw\">glōrior</div><div class=\"pos\">-ārī -ātus sum, <i>intr</i>(<i>tr</i>)<i>dep</i></div><div class=\"ori\">[gloria]</div><div class=\"def\">誇る, 自慢する 〈re;de [in] re〉.</div>\r\n","<div class=\"hw\">glōriābundus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[glorior]</div><div class=\"def\">得意になっている.</div>\r\n","<div class=\"hw\">glōriātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[glorior]</div><div class=\"def\">自慢.</div>\r\n","<div class=\"hw\">glōriātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[glorior]</div><div class=\"def\">自慢家, ほら吹き.</div>\r\n","<div class=\"hw\">glōriōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[gloria]</div><div class=\"def\"><num>①</num> うぬぼれた.</div><div class=\"def\"><num>②</num> 栄誉ある, 輝かしい.</div>\r\n","<div class=\"hw\">glōriōsē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://glōriōsus\">glōriōsus</a>]</div><div class=\"def\"><num>①</num> うぬぼれて.</div><div class=\"def\"><num>②</num> 輝かしく.</div>\r\n","<div class=\"hw\">glōs</div><div class=\"pos\">glōris <i>f</i></div><div class=\"def\">夫の姉妹.</div>\r\n","<div class=\"hw\">glūbō</div><div class=\"pos\">-ere, <i>tr</i>, <i>intr</i></div><div class=\"def\"><num0>Ⅰ</num0> (<i>tr</i>)樹皮をはぐ.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>intr</i>)樹皮がはがれる.</div>\r\n","<div class=\"hw\">glūma</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[glubo]</div><div class=\"def\">〘植〙穀類の頴果<SUB>えいか</SUB>をおおう鱗片状の葉, 頴包, はかま.</div>\r\n","<div class=\"hw\">glūs</div><div class=\"pos\">-ūtis, <SUP>◇</SUP><i>f</i></div><div class=\"def\">=<a href=\"entry://glūten\">gluten</a>.</div>\r\n","<div class=\"hw\">glūtaeofemorālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">〘解〙臀大腿部の.</div>\r\n","<div class=\"hw\">glūtaeus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"def\">〘解〙臀筋.</div>\r\n","<div class=\"hw\">glūten</div><div class=\"pos\">-tinis, <i>n</i></div><div class=\"def\">にかわ.</div>\r\n","<div class=\"hw\">glūtinum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">=<a href=\"entry://glūten\">gluten</a>.</div>\r\n","<div class=\"hw\">glūtināmentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[glutino]</div><div class=\"def\">(パピルス紙の)にかわづけされた部分.</div>\r\n","<div class=\"hw\">glūtinātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[glutino]</div><div class=\"def\"><num>①</num> にかわづけ.</div><div class=\"def\"><num>②</num> 傷口をふさぐこと.</div>\r\n","<div class=\"hw\">glūtinātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[↓<a href=\"entry://glūtinō\">glūtinō</a>]</div><div class=\"def\">(書巻をつくるために)パピルス紙をにかわづけする者.</div>\r\n","<div class=\"hw\">glūtinō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[gluten]</div><div class=\"def\"><num>①</num> にかわづけする.</div><div class=\"def\"><num>②</num> (傷口を)ふさぐ, 接合する.</div>\r\n","<div class=\"hw\">glūtinōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[gluten]</div><div class=\"def\">粘着性の, 粘る.</div>\r\n","<div class=\"hw\">glūtiō, gluttiō</div><div class=\"pos\">-īre -īvī [-iī] -ītum, <i>tr</i></div><div class=\"def\">のみ込む.</div>\r\n","<div class=\"hw\">glūtus<SUP>1</SUP>, gluttus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>cf</i>. glutio]</div><div class=\"def\">のみ込むこと.</div><hr><div class=\"hw\">glūtus<SUP>2</SUP>, gluttus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>cf</i>. gluten]</div><div class=\"def\">粘着する.</div>\r\n","<div class=\"hw\">Gnaeus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">グナエウス《ローマ人の個人名(略形は Cn.)》.</div>\r\n","<div class=\"hw\">Gnathō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">グナトー(ン)《Terentius の喜劇 <i>Eunuchus</i> 「宦官」 に登場する食客》.</div>\r\n","<div class=\"hw\">Gnid-</div><div class=\"def\">⇒Cnid-.</div>\r\n","<div class=\"hw\">gnoscō</div><div class=\"pos\">-ere, <i>tr</i></div><div class=\"def\">《古形》=<a href=\"entry://noscō\">nosco</a>.</div>\r\n","<div class=\"hw\">gnosticē</div><div class=\"pos\">-ēs, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">洞察力.</div>\r\n","<div class=\"hw\">Gnosticī</div><div class=\"pos\">-ōrum, <SUP>◇</SUP><i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">グノーシス派《初期キリスト教会で異端とされた》.</div>\r\n","<div class=\"hw\">gnāritās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[gnarus]</div><div class=\"def\">知識.</div>\r\n","<div class=\"hw\">gnāruris</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">=<a href=\"entry://gnārus\">gnarus</a>.</div>\r\n","<div class=\"hw\">gnārus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>cf. </i>(g)nosco]</div><div class=\"def\"><num>①</num> よく知っている, 精通している 〈+<i>gen</i>〉.</div><div class=\"def\"><num>②</num> 知られた, 周知の 〈+<i>dat</i>〉.</div>\r\n","<div class=\"hw\">gnāt-</div><div class=\"def\">⇒nat-.</div>\r\n","<div class=\"hw\">Gnātia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">=<a href=\"entry://Egnātia\">Egnatia</a>.</div>\r\n","<div class=\"hw\">gnāv-</div><div class=\"def\">⇒nav-.</div>\r\n","<div class=\"hw\">gnōbilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">《古形》=<a href=\"entry://nōbilis\">nobilis</a>.</div>\r\n","<div class=\"hw\">gnōmē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">格言, 金言.</div>\r\n","<div class=\"hw\">gnōmōn</div><div class=\"pos\">-monis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(日時計の)針.</div>\r\n","<div class=\"hw\">Gnōsia, Cnōs-</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">Creta 島の女(=<a href=\"entry://Ariadna\">Ariadna</a>).</div>\r\n","<div class=\"hw\">Gnōsiacus, Cnōs-</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Gnōsius\">Gnosius</a>.</div>\r\n","<div class=\"hw\">Gnōsias, Cnōs-</div><div class=\"pos\">-adis, <B>Gnōsis, Cnōs-</B> -idis, <i>adj f</i></div><div class=\"def\"><num>①</num> Gnosus の;Creta 島の.</div><div class=\"def\"><num>②</num> (名詞として)Creta 島の女(=<a href=\"entry://Ariadna\">Ariadna</a>).</div>\r\n","<div class=\"hw\">Gnōsius, Cnōs-</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Gnosus の;Creta 島の.</div>\r\n","<div class=\"hw\">Gnōsus, -os, Cnōsus, -os, Gnossus, -os, Cnossus, -os</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">グノースス, <SUP>*</SUP>-ソス《Creta 島北岸の古都;ミノス文明の中心地》.</div>\r\n","<div class=\"hw\">Gomphensis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">Gomphi の.</div><div class=\"hw2\"><b>Gomphensēs</b></div><div class=\"pos2\">-ium, <i>m pl</i></div><div class=\"def2\">Gomphi の住民.</div>\r\n","<div class=\"hw\">gomphus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">釘.</div>\r\n","<div class=\"hw\">Gomphī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ゴンピー, <SUP>*</SUP>-ポイ《Thessalia 西部の町》.</div>\r\n","<div class=\"hw\">gomphōsis</div><div class=\"pos\">-is, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘解〙丁植.</div>\r\n","<div class=\"hw\">gonium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘生物〙生殖原細胞.</div>\r\n","<div class=\"hw\">Gonnī</div><div class=\"pos\">-ōrum, <i>m pl</i>, <B>-us</B> -ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ゴンニー, <SUP>*</SUP>-ノイ《Thessalia 北東部の町》.</div>\r\n","<div class=\"hw\">gonorrhoea</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘病〙淋疾, 淋病.</div>\r\n","<div class=\"hw\">gonothēca</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘動〙生殖体包.</div>\r\n","<div class=\"hw\">Gordaeī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">=<a href=\"entry://Corduēnī\">Cordueni</a>.</div>\r\n","<div class=\"hw\">Gordium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ゴルディウム, <SUP>*</SUP>-オン《Phrygia の町》.</div>\r\n","<div class=\"hw\">Gordius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ゴルディウス, <SUP>*</SUP>-オス《Gordium の王;その戦車のくびきの解けない結び目で有名;Alexander 大王がこれを断ち切った》.</div>\r\n","<div class=\"hw\">Gord(y)aeī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">=<a href=\"entry://Corduēnī\">Cordueni</a>.</div>\r\n","<div class=\"hw\">Gorgiās</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ゴルギアース《Socrates と同時代の哲学者・ソフィスト(前485?‐?380);Sicilia 島の Leontini 出身》.</div>\r\n","<div class=\"hw\">Gorgobina</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ゴルゴビナ《Aquitania にあった Boii 族の町》.</div>\r\n","<div class=\"hw\">Gorgona</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">=<a href=\"entry://Gorgō(n)\">Gorgo</a>.</div>\r\n","<div class=\"hw\">Gorgoneus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Gorgon の</div><div class=\"ex\"><i>equus</i> ～ (<author>O<small>V</small></author>)<span class=\"ext\">=<a href=\"entry://Pēgasus\">Pegasus</a></span></div><div class=\"ex\"><i>lacus</i> ～ (<author>P<small>ROP</small></author>)<span class=\"ext\">=<a href=\"entry://Hippocrēnē\">Hippocrene</a> の泉.</span></div>\r\n","<div class=\"hw\">Gorgē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙ゴルゲー《Oeneus の娘で Meleager と Deianira の姉妹》.</div>\r\n","<div class=\"hw\">Gorgō(n)</div><div class=\"pos\">-onis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘神話〙ゴルゴー(ン)《Phorcus の三人の娘(Sthenno, Euryale, Medusa)の一人;特に Medusa を指す》.</div>\r\n","<div class=\"hw\">Gorneae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"def\">ゴルネアエ《Armenia の城塞》.</div>\r\n","<div class=\"hw\">Gortȳna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ゴルテューナ, <SUP>*</SUP>-テューン《Creta 島中央部の町》.</div>\r\n","<div class=\"hw\">Gortȳniacus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Gortȳnius\">Gortynius</a>.</div>\r\n","<div class=\"hw\">Gortȳnis</div><div class=\"pos\">-idis, <i>adj f</i></div><div class=\"def\">=<a href=\"entry://Gortȳnius\">Gortynius</a>.</div>\r\n","<div class=\"hw\">Gortȳnius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Gortyna の;Creta 島の.</div><div class=\"hw2\"><b>Gortȳniī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Gortyna の住民.</div>\r\n","<div class=\"hw\">gossypinus</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"def\">〘植〙ワタ(綿).</div>\r\n","<div class=\"hw\">gossypium, -on</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">=<a href=\"entry://gossypinus\">gossypinus</a></div><div class=\"ex\"><SUP>◇</SUP>～ <i>absorbens</i><span class=\"ext\">〘医〙脱脂綿</span></div><div class=\"ex\"><SUP>◇</SUP>～ <i>purificatum</i><span class=\"ext\">〘医〙精製綿.</span></div>\r\n","<div class=\"hw\">Gothicus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">Gothi 族の.</div>\r\n","<div class=\"hw\">Gothī</div><div class=\"pos\">-ōrum, <SUP>◇</SUP><i>m pl</i></div><div class=\"def\">ゴティー, <SUP>∥</SUP>ゴート族《Germania 北部にいた部族》.</div>\r\n","<div class=\"hw\">Got(h)īnī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ゴティーニー《現 Kraków 付近にいたケルト系一部族》.</div>\r\n","<div class=\"hw\">Got(h)ōnēs</div><div class=\"pos\">-um, <i>m pl</i></div><div class=\"def\">ゴトーネース《Germania にいた一部族》.</div>\r\n","<div class=\"hw\">grabātus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">簡易ベッド.</div>\r\n","<div class=\"hw\">Gracchus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">グラックス《Sempronia 氏族に属する家名;特に <i>Ti</i>. <i>Sempronius</i> ～ の二人の息子 <i>Ti</i>.(前163‐133)と <i>C. </i>(前153‐121)(=Gracchi「グラックス兄弟」)》.</div>\r\n","<div class=\"hw\">Gracchānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Gracchus の.</div>\r\n","<div class=\"hw\">gracilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\"><num>①</num> 細い, やせた, ほっそりした.</div><div class=\"def\"><num>②</num> 乏しい, 貧弱な</div><div class=\"ex\"><i>vindemiae graciles</i> (<author>P<small>LIN</small> M<small>IN</small></author>)<span class=\"ext\">乏しいブドウの収穫.</span></div><div class=\"def\"><num>③</num> (文体が)簡素な, 飾りのない.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP>〘解〙薄筋の.</div>\r\n","<div class=\"hw\">graciliter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[gracilis]</div><div class=\"def\"><num>①</num> 細く, ほっそりとして.</div><div class=\"def\"><num>②</num> 簡素に.</div>\r\n","<div class=\"hw\">gracilitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://gracilis\">gracilis</a>]</div><div class=\"def\"><num>①</num> やせていること, ほっそりしていること.</div><div class=\"def\"><num>②</num> (文体の)簡素, 飾りのないこと.</div>\r\n","<div class=\"hw\">gradior</div><div class=\"pos\">-dī gressus sum, <i>intr dep</i></div><div class=\"def\">歩く, 進む.</div>\r\n","<div class=\"hw\">gradus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[<i>cf</i>. gradior]</div><div class=\"def\"><num>①</num> 歩み, 足どり, 歩調</div><div class=\"ex\"><i>suspenso gradu</i> (<author>T<small>ER</small></author>)<span class=\"ext\">忍び足で</span></div><div class=\"ex\"><i>citato</i> [<i>pleno</i>] <i>gradu</i> (<author>L<small>IV</small></author>)<span class=\"ext\">駆け足で.</span></div><div class=\"def\"><num>②</num> 近づくこと, 前進.</div><div class=\"def\"><num>③</num> 持ち場, 部署</div><div class=\"ex\"><i>hostes gradu demoti</i> (<author>L<small>IV</small></author>)<span class=\"ext\">敵はその持ち場から追い払われた.</span></div><div class=\"def\"><num>④</num> 段, 階段.</div><div class=\"def\"><num>⑤</num> 階級, 地位, 身分.</div><div class=\"def\"><num>⑥</num> 程度, 段階</div><div class=\"ex\"><i>omnes gradūs aetatis</i> (<author>C<small>IC</small></author>)<span class=\"ext\">人生のすべての段階.</span></div>\r\n","<div class=\"hw\">graduāle</div><div class=\"pos\">-is, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[↓<a href=\"entry://gradus\">gradus</a>]</div><div class=\"def\">〘カト〙昇階唱.</div>\r\n","<div class=\"hw\">gradālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[gradus]</div><div class=\"def\">漸進的[段階的]な.</div>\r\n","<div class=\"hw\">gradārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[gradus]</div><div class=\"def\">一歩一歩の, 着実な.</div>\r\n","<div class=\"hw\">gradātim</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[gradus]</div><div class=\"def\">一歩一歩と, 段々に.</div>\r\n","<div class=\"hw\">gradātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[gradus]</div><div class=\"def\"><num>①</num> (通例 <i>pl</i>)(劇場の)階段席.</div><div class=\"def\"><num>②</num> 〘修〙漸層法(=<a href=\"entry://clīmax\">climax</a>).</div>\r\n","<div class=\"hw\">gradātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[gradus]</div><div class=\"def\">段の付いた.</div>\r\n","<div class=\"hw\">gradī</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://gradior\">gradior</a>.</div>\r\n","<div class=\"hw\">Graeae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘神話〙グラエアエ, <SUP>*</SUP>グライアイ《「白髪の女たち」の意;Phorcus の三人の娘たち;Gorgones の姉妹でその保護者;生まれた時から白髪で, 一眼一歯を共有していた》.</div>\r\n","<div class=\"hw\">Graecia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">グラエキア, <SUP>∥</SUP>ギリシア</div><div class=\"ex\"><i>Magna</i> ～ (<author>C<small>IC</small></author>)<span class=\"ext\">マグナ・グラエキア《ギリシア人が多数の植民市を建設したイタリア南部地方》.</span></div>\r\n","<div class=\"hw\">graecismus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"def\">ギリシア語法, ギリシア語風の表現.</div>\r\n","<div class=\"hw\">graecissātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://graecissō\">graecissō</a>]</div><div class=\"def\">ギリシア風にすること, ギリシア化.</div>\r\n","<div class=\"hw\">graecissō</div><div class=\"pos\">-āre, <i>intr</i></div><div class=\"def\">ギリシア人をまねる, ギリシア風にする.</div>\r\n","<div class=\"hw\">Graecitās</div><div class=\"pos\">-ātis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[Graecus]</div><div class=\"def\">ギリシア的なもの, ギリシア語.</div>\r\n","<div class=\"hw\">graecor</div><div class=\"pos\">-ārī -ātus sum, <i>intr dep</i></div><div class=\"ori\">[Graecus]</div><div class=\"def\">ギリシア人をまねる, ギリシア風にする.</div>\r\n","<div class=\"hw\">Graecostasis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"ori\">[Graecus/<i>Gk</i>▷στ<img class=\"font\" src=\"img/A146.png\">σι<img class=\"font\" src=\"img/A153.png\">◁]</div><div class=\"def\">(「ギリシア人の場所」の意)ギリシア(のち他国の)使節が滞在したローマ市内の建物.</div>\r\n","<div class=\"hw\">Graeculus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"ori\">[Graecus]</div><div class=\"def\">(軽蔑的に)(くだらない)ギリシア(人)の.</div><hr><div class=\"hw\">Graeculus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"def\">(軽蔑的に)(くだらない)ギリシア人.</div>\r\n","<div class=\"hw\">Graecum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://Graecus\">Graecus<SUP>1</SUP></a>]</div><div class=\"def\">ギリシア語.</div>\r\n","<div class=\"hw\">Graecus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">ギリシアの</div><div class=\"ex\"><i>lingua Graeca</i> (<author>C<small>IC</small></author>)<span class=\"ext\">ギリシア語</span></div><div class=\"ex\"><i>litterae Graecae</i> (<author>C<small>IC</small></author>)<span class=\"ext\">ギリシアの文芸</span></div><div class=\"ex\"><i>Graecā fide mercari</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">現金で取引する《ローマ人はギリシア人の信義を疑問視したので》.</span></div><hr><div class=\"hw\">Graecus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ギリシア人.</div>\r\n","<div class=\"hw\">Graecānicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">ギリシア起原の;ギリシア風の, ギリシア的な.</div>\r\n","<div class=\"hw\">Graecātim</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"def\">ギリシア風に.</div>\r\n","<div class=\"hw\">graecātus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[graecor]</div><div class=\"def\">ギリシア人をまねた, ギリシア風にした.</div>\r\n","<div class=\"hw\">Graecē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[Graecus]</div><div class=\"def\">ギリシア語で.</div>\r\n","<div class=\"hw\">Graecī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">グラエキー, <SUP>*</SUP>グライコイ, <SUP>∥</SUP>ギリシア人.</div>\r\n","<div class=\"hw\">Graiī, Grāī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">=<a href=\"entry://Graecī\">Graeci</a>.</div>\r\n","<div class=\"hw\">grallae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"def\">竹馬.</div>\r\n","<div class=\"hw\">grallātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[↑<a href=\"entry://grallae\">grallae</a>]</div><div class=\"def\">竹馬に乗る人.</div>\r\n","<div class=\"hw\">gramma</div><div class=\"pos\">-atos, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 文字.</div><div class=\"def\"><num>②</num> 重量単位(=<a href=\"entry://scrīpulum\">scripulum</a>).</div>\r\n","<div class=\"hw\">grammateus</div><div class=\"pos\">-eōs, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">書記.</div>\r\n","<div class=\"hw\">grammatica</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">文法;文献学.</div>\r\n","<div class=\"hw\">grammaticus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">文法の.</div><hr><div class=\"hw\">grammaticus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">文法家;文献学者.</div>\r\n","<div class=\"hw\">grammaticālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://grammatica\">grammatica</a>]</div><div class=\"def\">文法の.</div>\r\n","<div class=\"hw\">grammaticāliter</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://grammaticālis\">grammaticālis</a>]</div><div class=\"def\">文法上, 文法的に.</div>\r\n","<div class=\"hw\">grammaticē<SUP>1</SUP></div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"def\">=<a href=\"entry://grammatica\">grammatica</a>.</div><hr><div class=\"hw\">grammaticē<SUP>2</SUP></div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://grammaticus\">grammaticus<SUP>1</SUP></a>]</div><div class=\"def\">文法的に.</div>\r\n","<div class=\"hw\">grammatista</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">文字を教える人, 初学者の教師.</div>\r\n","<div class=\"hw\">grammicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">線の, 幾何学的な.</div>\r\n","<div class=\"hw\">grandaevus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[grandis/aevum]</div><div class=\"def\">高齢の, 老齢の.</div>\r\n","<div class=\"hw\">grandescō</div><div class=\"pos\">-ere, <i>intr inch</i></div><div class=\"ori\">[grandis]</div><div class=\"def\">大きくなる, 増大する, 成長する.</div>\r\n","<div class=\"hw\">grandiculus</div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"ori\">[grandis]</div><div class=\"def\">やや大きな.</div>\r\n","<div class=\"hw\">grandifer</div><div class=\"pos\">-fere -ferum, <i>adj</i></div><div class=\"ori\">[grandis/fero]</div><div class=\"def\">豊かな実りをもたらす, 豊作の.</div>\r\n","<div class=\"hw\">grandiloquus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[grandis/loquor]</div><div class=\"def\"><num>①</num> 荘重な文体を用いる.</div><div class=\"def\"><num>②</num> 大言壮語する, 自慢する.</div>\r\n","<div class=\"hw\">grandinat</div><div class=\"pos\">-āre, <i>intr impers</i></div><div class=\"ori\">[grando]</div><div class=\"def\">雹が降る.</div>\r\n","<div class=\"hw\">grandis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\"><num>①</num> 大きな.</div><div class=\"def\"><num>②</num> (十分に)成長した, 成熟した.</div><div class=\"def\"><num>③</num> 大量の, 多数の.</div><div class=\"def\"><num>④</num> はなはだしい, 激しい.</div><div class=\"def\"><num>⑤</num> 偉大な;重大な.</div><div class=\"def\"><num>⑥</num> (文体が)高尚な, 荘重な.</div>\r\n","<div class=\"hw\">grandiscāpius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://grandis\">grandis</a>/scapus]</div><div class=\"def\">太い幹の.</div>\r\n","<div class=\"hw\">granditer</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[grandis]</div><div class=\"def\"><num>①</num> 大いに, 非常に.</div><div class=\"def\"><num>②</num> 荘重に, 気高く.</div>\r\n","<div class=\"hw\">granditās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[grandis]</div><div class=\"def\"><num>①</num> 高齢.</div><div class=\"def\"><num>②</num> (文体の)荘重, 気高さ.</div>\r\n","<div class=\"hw\">grandiusculus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj dim</i></div><div class=\"ori\">[grandis]</div><div class=\"def\">かなり成長した.</div>\r\n","<div class=\"hw\">grandiō</div><div class=\"pos\">-īre, <i>tr</i>, <i>intr</i></div><div class=\"ori\">[↓<a href=\"entry://grandis\">grandis</a>]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>tr</i>)大きくする.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>intr</i>)大きくなる.</div>\r\n","<div class=\"hw\">grandō</div><div class=\"pos\">-dinis, <i>f</i></div><div class=\"def\">雹.</div>\r\n","<div class=\"hw\">Grannus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">《碑》(Germania, Dacia, Scotia における)Apollo の添え名.</div>\r\n","<div class=\"hw\">graphicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 絵画的な.</div><div class=\"def\"><num>②</num> みごとな, とびきりの.</div>\r\n","<div class=\"hw\">graphicē<SUP>1</SUP></div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">画法.</div><hr><div class=\"hw\">graphicē<SUP>2</SUP></div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://graphicus\">graphicus</a>]</div><div class=\"def\"><num>①</num> 画家のように;(文体が)生き生きと, 迫真的に.</div><div class=\"def\"><num>②</num> みごとに, 巧みに.</div>\r\n","<div class=\"hw\">graphis</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">絵筆.</div>\r\n","<div class=\"hw\">graphium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">尖筆.</div>\r\n","<div class=\"hw\">graphiārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[graphium]</div><div class=\"def\">尖筆の.</div>\r\n","<div class=\"hw\">grassor</div><div class=\"pos\">-ārī -ātus sum, <i>intr dep freq</i></div><div class=\"ori\">[gradior]</div><div class=\"def\"><num>①</num> (獲物を求めて)うろつきまわる.</div><div class=\"def\"><num>②</num> 進む</div><div class=\"ex\"><i>ad gloriam virtutis viā grassari</i> (<author>S<small>ALL</small></author>)<span class=\"ext\">栄誉を求めて徳の道を進む.</span></div><div class=\"def\"><num>③</num> 行動する, 処する</div><div class=\"ex\"><i>superbe grassatos</i> (<author>S<small>UET</small></author>)<span class=\"ext\">傲慢なふるまいを見せていた者どもを.</span></div><div class=\"def\"><num>④</num> 襲いかかる, あばれまわる.</div>\r\n","<div class=\"hw\">grassātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[grassor]</div><div class=\"def\">こそこそうろつきまわること.</div>\r\n","<div class=\"hw\">grassātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[grassor]</div><div class=\"def\"><num>①</num> 放浪者.</div><div class=\"def\"><num>②</num> 追いはぎ.</div>\r\n","<div class=\"hw\">grassātūra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://grassor\">grassor</a>]</div><div class=\"def\">追いはぎ行為.</div>\r\n","<div class=\"hw\">Graupius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><i>mons</i> ～ (<author>T<small>AC</small></author>) グラウピウス山《Caledonia の山地;現 Grampian Hills》.</div>\r\n","<div class=\"hw\">gravanter</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"def\">=<a href=\"entry://gravātē\">gravate</a>.</div>\r\n","<div class=\"hw\">graveolens</div><div class=\"pos\">-entis, <i>adj</i></div><div class=\"ori\">[gravis/olens]</div><div class=\"def\"><num>①</num> 強い匂いのする;悪臭を放つ.</div>\r\n","<div class=\"hw\">gravescō</div><div class=\"pos\">-ere, <i>intr inch</i></div><div class=\"ori\">[gravis]</div><div class=\"def\"><num>①</num> 重くなる.</div><div class=\"def\"><num>②</num> 悪化する.</div>\r\n","<div class=\"hw\">graviditās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[gravidus]</div><div class=\"def\">妊娠.</div>\r\n","<div class=\"hw\">gravidus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://gravis\">gravis</a>]</div><div class=\"def\"><num>①</num> 妊娠している.</div><div class=\"def\"><num>②</num> いっぱいの, 満ちた 〈re〉.</div>\r\n","<div class=\"hw\">gravidō<SUP>2</SUP></div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://gravidus\">gravidus</a>]</div><div class=\"def\">妊娠させる.</div>\r\n","<div class=\"hw\">gravis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\"><num>①</num> 重い.</div><div class=\"def\"><num>②</num> 困難な, 面倒な, 厄介な.</div><div class=\"def\"><num>③</num> きびしい, ひどい, 激しい</div><div class=\"ex\"><i>grave odium</i> (<author>C<small>IC</small></author>)<span class=\"ext\">激しい憎悪</span></div><div class=\"ex\">～ <i>autumnus</i> (<author>C<small>AES</small></author>)<span class=\"ext\">きびしい秋.</span></div><div class=\"def\"><num>④</num> (においが)強烈な, 悪臭を放つ.</div><div class=\"def\"><num>⑤</num> (音が)低い.</div><div class=\"def\"><num>⑥</num> 重要な, 有力な</div><div class=\"ex\"><i>testis</i> ～ (<author>C<small>IC</small></author>)<span class=\"ext\">重要な証人.</span></div><div class=\"def\"><num>⑦</num> 威厳のある, まじめな.</div><div class=\"def\"><num>⑧</num> ゆゆしい, 深刻な.</div><div class=\"def\"><num>⑨</num> (文体が)荘重な, 高尚な.</div><div class=\"def\"><num>⑩</num> 重装備の.</div><div class=\"def\"><num>⑪</num> 消化しにくい.</div><div class=\"def\"><num>⑫</num> 重くなった, 圧迫された</div><div class=\"ex\"><i>morbo</i> ～ (<author>V<small>ERG</small></author>)<span class=\"ext\">病気でやつれた</span></div><div class=\"ex\"><i>aetate</i> ～ (<author>L<small>IV</small></author>)<span class=\"ext\">年老いて身動きもままならぬ.</span></div><div class=\"def\"><num>⑬</num> 妊娠している.</div>\r\n","<div class=\"hw\">Graviscae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"def\">グラウィスカエ《Etruria の町》.</div>\r\n","<div class=\"hw\">graviter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[gravis]</div><div class=\"def\"><num>①</num> 重く.</div><div class=\"def\"><num>②</num> 低い音で.</div><div class=\"def\"><num>③</num> 荘重に, 威厳をもって.</div><div class=\"def\"><num>④</num> いやいや, しぶしぶ.</div><div class=\"def\"><num>⑤</num> きびしく, ひどく, 激しく.</div><div class=\"def\"><num>⑥</num> ゆゆしく, 深刻に.</div>\r\n","<div class=\"hw\">gravitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[gravis]</div><div class=\"def\"><num>①</num> 重さ.</div><div class=\"def\"><num>②</num> (身体・感覚の)だるさ, 鈍さ;妊娠.</div><div class=\"def\"><num>③</num> 重要さ.</div><div class=\"def\"><num>④</num> 威厳, まじめさ.</div><div class=\"def\"><num>⑤</num> (文体の)荘重.</div><div class=\"def\"><num>⑥</num> きびしさ, 苛酷.</div><div class=\"def\"><num>⑦</num> ゆゆしいこと, 深刻さ.</div>\r\n","<div class=\"hw\">gravitūdō</div><div class=\"pos\">-dinis, <i>f</i></div><div class=\"ori\">[gravis]</div><div class=\"def\">鼻かぜ;重苦しい感じ.</div>\r\n","<div class=\"hw\">gravāmen</div><div class=\"pos\">-minis, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[gravo]</div><div class=\"def\">面倒, 厄介.</div>\r\n","<div class=\"hw\">gravātim</div><div class=\"pos\"><i>adv</i></div><div class=\"def\">=<a href=\"entry://gravātē\">gravate</a>.</div>\r\n","<div class=\"hw\">gravātē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[gravo]</div><div class=\"def\">いやいや, しぶしぶ.</div>\r\n","<div class=\"hw\">gravēdinōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://gravēdō\">gravēdō</a>]</div><div class=\"def\">かぜをひきやすい.</div>\r\n","<div class=\"hw\">gravēdō</div><div class=\"pos\">-dinis, <i>f</i></div><div class=\"ori\">[gravis]</div><div class=\"def\"><num>①</num> 鼻かぜ.</div><div class=\"def\"><num>②</num> 重苦しい感じ, 圧迫感.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 妊娠.</div>\r\n","<div class=\"hw\">gravīdō<SUP>1</SUP></div><div class=\"pos\">-dinis, <i>f</i></div><div class=\"def\">=<a href=\"entry://gravēdō\">gravedo</a>.</div>\r\n","<div class=\"hw\">gravō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[gravis]</div><div class=\"def\"><num>①</num> 重くする, 圧迫する, 荷を負わせる.</div><div class=\"def\"><num>②</num> (特に <i>dep</i> で)煩わしく感じる 〈alqd;+<i>inf</i>;+<i>acc c. inf</i>〉</div><div class=\"ex\"><i>neque gravor quid sentiam dicere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">煩わしいと思わずに私がどう感じるか言うことにしよう.</span></div><div class=\"def\"><num>③</num> 増大させる, 悪化させる.</div>\r\n","<div class=\"hw\">gregālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[grex]</div><div class=\"def\"><num>①</num> 群れに属する, 群れをなす.</div><div class=\"def\"><num>②</num> 仲間の.</div><div class=\"def\"><num>③</num> 普通の, ありふれた.</div>\r\n","<div class=\"hw\">gregālēs</div><div class=\"pos\">-ium, <i>m pl</i></div><div class=\"ori\">[↓<a href=\"entry://gregālis\">gregālis</a>]</div><div class=\"def\">仲間, 同僚, 同志.</div>\r\n","<div class=\"hw\">gregārius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[grex]</div><div class=\"def\"><num>①</num> 群れに属する, 群れをなす.</div><div class=\"def\"><num>②</num> 普通の, ありふれた</div><div class=\"ex\"><i>miles</i> ～ (<author>C<small>IC</small></author>)<span class=\"ext\">兵卒.</span></div><hr><div class=\"hw\">gregārius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 家畜番, 牧夫.</div><div class=\"def\"><num>②</num> 兵卒.</div><div class=\"def\"><num>③</num> 《碑》下級剣闘士.</div>\r\n","<div class=\"hw\">gregātim</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[grex]</div><div class=\"def\">群れをなして, 大勢で.</div>\r\n","<div class=\"hw\">gregō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[grex]</div><div class=\"def\">集める, 群れの中へ入れる.</div>\r\n","<div class=\"hw\">gremium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\"><num>①</num> ひざ, ふところ.</div><div class=\"def\"><num>②</num> 中央部, 内部.</div>\r\n","<div class=\"hw\">gressus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://gradior\">gradior</a>.</div><hr><div class=\"hw\">gressus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> 歩み.</div><div class=\"def\"><num>②</num> 航路.</div>\r\n","<div class=\"hw\">grex</div><div class=\"pos\">gregis, <i>m</i></div><div class=\"def\"><num>①</num> 群れ.</div><div class=\"def\"><num>②</num> 大勢, 群集.</div><div class=\"def\"><num>③</num> 部隊.</div><div class=\"def\"><num>④</num> 学派.</div>\r\n","<div class=\"hw\">grillus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">=<a href=\"entry://gryllus\">gryllus</a>.</div>\r\n","<div class=\"hw\">grossitūdō</div><div class=\"pos\">-dinis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[grossus<SUP>2</SUP>]</div><div class=\"def\">厚さ(=<a href=\"entry://crassitūdō\">crassitudo</a>).</div>\r\n","<div class=\"hw\">grossus<SUP>1</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">〘植〙未熟なイチジク.</div><hr><div class=\"hw\">grossus<SUP>2</SUP></div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">厚い.</div>\r\n","<div class=\"hw\">Grudiī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">グルディイー《Gallia Belgica にいた一部族》.</div>\r\n","<div class=\"hw\">gruis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\">=<a href=\"entry://grūs\">grus</a>.</div>\r\n","<div class=\"hw\">grund-</div><div class=\"def\">⇒grunn-.</div>\r\n","<div class=\"hw\">grunniō</div><div class=\"pos\">-īre -īvī [-iī] -ītum, <i>intr</i></div><div class=\"def\">(特にブタが)ブーブー鳴く.</div>\r\n","<div class=\"hw\">grunnītus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[↑<a href=\"entry://grunniō\">grunniō</a>]</div><div class=\"def\">(ブタが)ブーブー鳴くこと.</div>\r\n","<div class=\"hw\">gruō</div><div class=\"pos\">-ere, <i>intr</i></div><div class=\"ori\">[<i>cf. </i> grus]</div><div class=\"def\">ツルが鳴く.</div>\r\n","<div class=\"hw\">gryllus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘昆〙バッタ, コオロギ.</div>\r\n","<div class=\"hw\">gryps</div><div class=\"pos\">-ȳpis, <B>grȳpus<SUP>1</SUP></B> -ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘神話〙グリュプス《ライオンの胴体にワシの頭と翼を持つ怪獣》</div><div class=\"ex\"><i>jungentur jam grypes equis</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">やがてグリュプスが馬とつがうであろう(=不可能のことが可能になるであろう).</span></div>\r\n","<div class=\"hw\">Grȳnēus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Grynia の.</div>\r\n","<div class=\"hw\">Grȳnīa</div><div class=\"pos\">-ae, <i>f</i>, <B>Grȳnium</B> -ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">グリューニーア, <SUP>*</SUP>-ネイア《Aeolis の港町;Apollo の神殿と神託所があった》.</div>\r\n","<div class=\"hw\">grȳpus<SUP>2</SUP></div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">かぎ鼻の人.</div>\r\n","<div class=\"hw\">grāculus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">〘鳥〙コクマルガラス.</div>\r\n","<div class=\"hw\">Grādīvus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">(「戦いにおいて進み出る者」の意)Mars の添え名.</div>\r\n","<div class=\"hw\">Grāiocelī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">グライヨケリー《Gallia Narbonensis にいた一部族》.</div>\r\n","<div class=\"hw\">Grāiugena</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[↓<a href=\"entry://Grāius\">Grāius<SUP>1</SUP></a>/gigno]</div><div class=\"def\">ギリシア生まれの人, ギリシア人.</div>\r\n","<div class=\"hw\">Grāius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> ギリシアの.</div><div class=\"def\"><num>②</num> <i>Alpes Graiae</i> (<author>P<small>LIN</small></author>) 現在のフランスとイタリアを結ぶ Petit-Saint-Bernard 峠(標高2, 188m)とその周辺の山.</div><hr><div class=\"hw\">Grāius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">(一人の)ギリシア人(通例 <i>pl</i>;⇒ <a href=\"entry://Graiī\">Graii</a>).</div>\r\n","<div class=\"hw\">grāmen</div><div class=\"pos\">-minis, <i>n</i></div><div class=\"def\"><num>①</num> 草.</div><div class=\"def\"><num>②</num> (一般に)草木, 植物.</div>\r\n","<div class=\"hw\">grāmiae, grāmae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"def\">目やに.</div>\r\n","<div class=\"hw\">grāmineus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[gramen]</div><div class=\"def\"><num>①</num> 草の.</div><div class=\"def\"><num>②</num> アシ(葦)の.</div>\r\n","<div class=\"hw\">grāminōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[gramen]</div><div class=\"def\">草の多い.</div>\r\n","<div class=\"hw\">grānea</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[granum]</div><div class=\"def\">穀物粉でつくったかゆ.</div>\r\n","<div class=\"hw\">grānifer</div><div class=\"pos\">-fera -ferum, <i>adj</i></div><div class=\"ori\">[granum/fero]</div><div class=\"def\">穀粒を運ぶ.</div>\r\n","<div class=\"hw\">Grānius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">グラーニウス《ローマ人の氏族名》.</div>\r\n","<div class=\"hw\">grānulum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n dim</i></div><div class=\"ori\">[↓<a href=\"entry://grānum\">grānum</a>]</div><div class=\"def\"><num>①</num> 小さな穀粒.</div><div class=\"def\"><num>②</num> 〘カト〙ロザリオの珠.</div>\r\n","<div class=\"hw\">grānulōsus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://grānulum\">grānulum</a>]</div><div class=\"def\">〘解〙顆粒の.</div>\r\n","<div class=\"hw\">grānum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\"><num>①</num> 穀粒.</div><div class=\"def\"><num>②</num> 種<SUB>たね</SUB>, 種子.</div>\r\n","<div class=\"hw\">grānārium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[granum]</div><div class=\"def\">穀物倉.</div>\r\n","<div class=\"hw\">grānātim</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[granum]</div><div class=\"def\">一粒ずつ.</div>\r\n","<div class=\"hw\">grānātum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://grānātus\">grānātus</a>]</div><div class=\"def\">〘植〙ザクロ(の実).</div>\r\n","<div class=\"hw\">grānātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[granum]</div><div class=\"def\">多くの種[粒]をもつ.</div>\r\n","<div class=\"hw\">Grānīcus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">グラーニークス, <SUP>*</SUP>-コス《Mysia の小川;そのほとりで Alexander 大王がペルシア軍を破った(前334)》.</div>\r\n","<div class=\"hw\">grānōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[granum]</div><div class=\"def\">種<SUB>たね</SUB>の多い.</div>\r\n","<div class=\"hw\">grātanter</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[grator]</div><div class=\"def\">喜んで.</div>\r\n","<div class=\"hw\">grātia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[gratus]</div><div class=\"def\"><num>①</num> 美しさ, 愛らしさ, 魅力.</div><div class=\"def\"><num>②</num> 好意, 尊敬, 愛情</div><div class=\"ex\"><i>ab Caesare gratiam inire</i> (<author>C<small>AES</small></author>)<span class=\"ext\">Caesar の好意をかちえる</span></div><div class=\"ex\"><i>cum Lucceio in gratiam redii</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私は Lucceius と和解した</span></div><div class=\"ex\"><i>grat(i)is</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">好意から, 無償[ただ]で.</span></div><div class=\"def\"><num>③</num> 親切, 尽力, 世話</div><div class=\"ex\"><i>meā gratiā</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">私のために</span></div><div class=\"ex\"><i>hominum gratiā</i> (<author>C<small>IC</small></author>)<span class=\"ext\">人々のために</span></div><div class=\"ex\"><i>exempli gratiā</i> (<author>Q<small>UINT</small></author>)<span class=\"ext\">例をあげれば, たとえば.</span></div><div class=\"def\"><num>④</num> 人気, 信望.</div><div class=\"def\"><num>⑤</num> 偏愛, えこひいき.</div><div class=\"def\"><num>⑥</num> 感謝</div><div class=\"ex\"><i>dis gratias pro meritis agere</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">神々にご加護のお礼を言う</span></div><div class=\"ex\"><i>fortunae gratiam habere</i> (<author>C<small>AES</small></author>)<span class=\"ext\">幸運(の女神)に感謝する</span></div><div class=\"ex\"><i>benignitate deum gratiam referre</i> (<author>T<small>AC</small></author>)<span class=\"ext\">神々のご好意に感謝をささげて報いる.</span></div><div class=\"def\"><num>⑦</num> (<i>pl</i> Gratiae)〘神話〙グラーティアエ《美と優雅の三女神;ギリシア神話の Charites に当たる;Aglaia 「輝き」, Euphrosyne 「喜び」, Thalia 「開花」 の三姉妹》.</div><div class=\"def\"><num>⑧</num> <SUP>◇</SUP>〘神学〙(神の)恵み, 恩寵.</div>\r\n","<div class=\"hw\">Grātidius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">グラーティディウス《ローマ人の氏族名》.</div>\r\n","<div class=\"hw\">grātificor</div><div class=\"pos\">-ārī -ātus sum, <i>intr</i>, <i>tr dep</i></div><div class=\"ori\">[gratus/facio]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>intr</i>)人を喜ばせる, 恩恵を施す 〈alci〉.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>tr</i>)与える 〈alci alqd〉.</div>\r\n","<div class=\"hw\">grātificus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[gratus/facio]</div><div class=\"def\">親切な.</div>\r\n","<div class=\"hw\">grātificātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[gratificor]</div><div class=\"def\">人を喜ばせること, 恩恵を施すこと, 親切.</div>\r\n","<div class=\"hw\">grātificō</div><div class=\"pos\">-āre, <i>intr</i>, <i>tr</i></div><div class=\"def\">=<a href=\"entry://grātificor\">gratificor</a>.</div>\r\n","<div class=\"hw\">grātitūdō</div><div class=\"pos\">-dinis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[gratus]</div><div class=\"def\">感謝, 謝意.</div>\r\n","<div class=\"hw\">Grātius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">グラーティウス《<i>Cynegetica</i> 「狩りの歌」 を著わしたローマの詩人;Ovidius と同時代》.</div>\r\n","<div class=\"hw\">grātiōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[gratia]</div><div class=\"def\"><num>①</num> 気に入られている, 好意を得ている 〈alci;apud alqm;in re〉.</div><div class=\"def\"><num>②</num> 魅力的な, 感じのよい.</div><div class=\"def\"><num>③</num> 好意的な, 親切な 〈in re;ad alqd〉.</div>\r\n","<div class=\"hw\">grātiōsē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://grātiōsus\">grātiōsus</a>]</div><div class=\"def\">(不公平に)親切に, えこひいきして.</div>\r\n","<div class=\"hw\">grātor</div><div class=\"pos\">-ārī -ātus, <i>intr dep</i></div><div class=\"def\">=<a href=\"entry://grātulor\">gratulor</a>.</div>\r\n","<div class=\"hw\">grātulanter</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[gratulor]</div><div class=\"def\">喜んで.</div>\r\n","<div class=\"hw\">grātulor</div><div class=\"pos\">-ārī -ātus sum, <i>intr</i>, <i>tr dep</i></div><div class=\"ori\">[↓<a href=\"entry://grātus\">grātus</a>]</div><div class=\"def\"><num>①</num> 祝賀[祝福]する 〈alci;de [in] re;alci alqd;+<i>acc c.inf</i>;quod〉.</div><div class=\"def\"><num>②</num> (神々に)感謝する 〈alci〉.</div>\r\n","<div class=\"hw\">grātulābundus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[gratulor]</div><div class=\"def\">祝賀[祝福]する.</div>\r\n","<div class=\"hw\">grātulātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[gratulor]</div><div class=\"def\"><num>①</num> 祝賀, 祝福.</div><div class=\"def\"><num>②</num> 感謝祭.</div>\r\n","<div class=\"hw\">grātulātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[↓<a href=\"entry://grātulor\">grātulor</a>]</div><div class=\"def\">祝賀[祝福]する人.</div>\r\n","<div class=\"hw\">grātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> 魅力的な, 感じのよい, 好ましい.</div><div class=\"def\"><num>②</num> 感謝に値する, ありがたい 〈alci〉.</div><div class=\"def\"><num>③</num> 感謝している</div><div class=\"ex\"><i>bene de me meritis gratum me praebeo</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私は私のために尽くしてくれた人々に謝意を表明する.</span></div>\r\n","<div class=\"hw\">grātuītus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[gratus]</div><div class=\"def\"><num>①</num> 無料の, 無償の.</div><div class=\"def\"><num>②</num> 買収されない.</div><div class=\"def\"><num>③</num> 無利子の.</div><div class=\"def\"><num>④</num> 十分な理由のない.</div>\r\n","<div class=\"hw\">grātuītō</div><div class=\"pos\"><i>adv</i>(<i>abl</i>)</div><div class=\"ori\">[↓<a href=\"entry://grātuītus\">grātuītus</a>]</div><div class=\"def\"><num>①</num> 無料で, 無償で.</div><div class=\"def\"><num>②</num> 十分な理由なく.</div>\r\n","<div class=\"hw\">grātē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[gratus]</div><div class=\"def\">喜んで, 感謝して.</div>\r\n","<div class=\"hw\">grātēs</div><div class=\"pos\">-ium, <i>f pl</i></div><div class=\"def\">(用例は <i>nom, acc,</i> および <i>abl</i> grātibus のみ)</div><div class=\"ori\">[gratus]</div><div class=\"def\">(特に神々への)感謝.</div>\r\n","<div class=\"hw\">grātīs, grātiīs</div><div class=\"pos\"><i>pl abl</i></div><div class=\"def\">⇒<a href=\"entry://grātia\">gratia</a>.</div>\r\n","<div class=\"hw\">grāvastellus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">白髪頭の老人.</div>\r\n","<div class=\"hw\">grīphus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">難問, なぞ.</div>\r\n","<div class=\"hw\">grīseus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">灰色の.</div>\r\n","<div class=\"hw\">grōma</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">照準器, 測量器.</div>\r\n","<div class=\"hw\">grōmaticus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://grōma\">grōma</a>]</div><div class=\"def\">測量の.</div>\r\n","<div class=\"hw\">grūma</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">=<a href=\"entry://grōma\">groma</a>.</div>\r\n","<div class=\"hw\">grūmus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">丘, 塚.</div>\r\n","<div class=\"hw\">grūs</div><div class=\"pos\">-uis, <i>f</i></div><div class=\"def\">〘鳥〙ツル.</div>\r\n","<div class=\"hw\">guajacolum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘薬〙グアヤコール.</div>\r\n","<div class=\"hw\">gubernius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">=<a href=\"entry://gubernātor\">gubernator 1</a>.</div>\r\n","<div class=\"hw\">guberniō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>m</i></div><div class=\"def\">=<a href=\"entry://gubernius\">gubernius</a>.</div>\r\n","<div class=\"hw\">gubernum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>cf. </i> guberno]</div><div class=\"def\">舵.</div>\r\n","<div class=\"hw\">gubernābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[guberno]</div><div class=\"def\">操縦されうる, 支配されうる.</div>\r\n","<div class=\"hw\">gubernāclum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">《詩》=<a href=\"entry://gubernāculum\">gubernaculum</a>.</div>\r\n","<div class=\"hw\">gubernāculum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[guberno]</div><div class=\"def\"><num>①</num> 舵.</div><div class=\"def\"><num>②</num> 操縦;指揮, 支配.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘解〙導帯.</div>\r\n","<div class=\"hw\">gubernātiō</div><div class=\"pos\">-ōnis <i>f</i></div><div class=\"ori\">[guberno]</div><div class=\"def\"><num>①</num> 舵を取ること, 操縦.</div><div class=\"def\"><num>②</num> 指揮, 支配.</div>\r\n","<div class=\"hw\">gubernātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[guberno]</div><div class=\"def\"><num>①</num> 舵手.</div><div class=\"def\"><num>②</num> 指揮者, 支配者.</div>\r\n","<div class=\"hw\">gubernātrix</div><div class=\"pos\">-īcis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://gubernātor\">gubernātor</a>]</div><div class=\"def\">指揮者, 支配者《女性》.</div>\r\n","<div class=\"hw\">gubernō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 舵を取る, 操縦する.</div><div class=\"def\"><num>②</num> 指揮する, 支配する.</div>\r\n","<div class=\"hw\">guerra</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>G</i>]</div><div class=\"def\">戦い, 戦争.</div>\r\n","<div class=\"hw\">Gugernī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">=<a href=\"entry://Cugernī\">Cugerni</a>.</div>\r\n","<div class=\"hw\">gula</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 食道, のど.</div><div class=\"def\"><num>②</num> 大食, 食道楽.</div>\r\n","<div class=\"hw\">Gulussa, Gulūsa</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">グルッサ《Numidia の王 Masinissa の息子》.</div>\r\n","<div class=\"hw\">gulō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"ori\">[↑<a href=\"entry://gula\">gula</a>]</div><div class=\"def\">大食漢, 美食家.</div>\r\n","<div class=\"hw\">gulōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[gula]</div><div class=\"def\">大食の, 美食の.</div>\r\n","<div class=\"hw\">gulōsē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://gulōsus\">gulōsus</a>]</div><div class=\"def\">大食漢のように.</div>\r\n","<div class=\"hw\">gumia</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">大食漢, 美食家.</div>\r\n","<div class=\"hw\">guminasium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">=<a href=\"entry://gymnasium\">gymnasium</a>.</div>\r\n","<div class=\"hw\">gummi</div><div class=\"pos\"><i>indecl n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ゴム.</div>\r\n","<div class=\"hw\">gummōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://gummi\">gummi</a>]</div><div class=\"def\">ゴム性の.</div>\r\n","<div class=\"hw\">gunna</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">毛皮.</div>\r\n","<div class=\"hw\">gurdus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">愚か者, まぬけ.</div>\r\n","<div class=\"hw\">gurges</div><div class=\"pos\">-gitis, <i>m</i></div><div class=\"def\"><num>①</num> 渦, 渦巻.</div><div class=\"def\"><num>②</num> (大量の)水;海, 川.</div><div class=\"def\"><num>③</num> 深淵, 底なし沼.</div><div class=\"def\"><num>④</num> 浪費家.</div>\r\n","<div class=\"hw\">gurgitō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[↑<a href=\"entry://gurges\">gurges</a>]</div><div class=\"def\">いっぱいにする, あふれさせる 〈re〉.</div>\r\n","<div class=\"hw\">gurguliō<SUP>1</SUP></div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\">食道, のど, 気管.</div><hr><div class=\"hw\">gurguliō<SUP>2</SUP></div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\">=<a href=\"entry://curculiō\">curculio</a>.</div>\r\n","<div class=\"hw\">gurgustiolum</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[↓<a href=\"entry://gurgustium\">gurgustium</a>]</div><div class=\"def\">(小さな)あばら屋.</div>\r\n","<div class=\"hw\">gurgustium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[gurges]</div><div class=\"def\">小屋, あばら屋.</div>\r\n","<div class=\"hw\">gustus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> 試食, 味わうこと.</div><div class=\"def\"><num>②</num> 風味.</div><div class=\"def\"><num>③</num> 前菜.</div>\r\n","<div class=\"hw\">gustātus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[↓<a href=\"entry://gustō\">gustō</a>]</div><div class=\"def\"><num>①</num> 味わうこと.</div><div class=\"def\"><num>②</num> 味覚.</div><div class=\"def\"><num>③</num> 風味.</div>\r\n","<div class=\"hw\">gustātōrium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[gusto]</div><div class=\"def\">前菜用の皿;前菜.</div>\r\n","<div class=\"hw\">gustō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://gustus\">gustus</a>]</div><div class=\"def\"><num>①</num> 味わう, 試食する;少し食べる.</div><div class=\"def\"><num>②</num> 楽しむ, 享受する.</div><div class=\"def\"><num>③</num> 少し知る[経験する].</div>\r\n","<div class=\"hw\">gutta</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 滴, したたり.</div><div class=\"def\"><num>②</num> 斑点.</div><div class=\"def\"><num>③</num> 少量, 微量.</div>\r\n","<div class=\"hw\">guttapercha</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘化〙グッタペルカ.</div>\r\n","<div class=\"hw\">guttula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[gutta]</div><div class=\"def\">(小さな)滴.</div>\r\n","<div class=\"hw\">guttur</div><div class=\"pos\">-uris, <i>n</i></div><div class=\"def\"><num>①</num> のど, 気管.</div><div class=\"def\"><num>②</num> 大食.</div>\r\n","<div class=\"hw\">gutturōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://guttur\">guttur</a>]</div><div class=\"def\">〘病〙甲状腺肥大の.</div>\r\n","<div class=\"hw\">guttus, gūtus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[gutta]</div><div class=\"def\">細首の瓶.</div>\r\n","<div class=\"hw\">guttātim</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[gutta]</div><div class=\"def\">一滴ずつ.</div>\r\n","<div class=\"hw\">guttātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[gutta]</div><div class=\"def\">斑点のある, まだらの.</div>\r\n","<div class=\"hw\">Gyaros, -us</div><div class=\"pos\">-ī, <i>f</i>, <B>Gyara</B> -ae, <i>f</i>, <B>-a</B> -ōrum, <i>n pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ギュアロス《エーゲ海の不毛の島;Cyclades 諸島の一つ;ローマ帝政時代の流刑地》.</div>\r\n","<div class=\"hw\">Gylippus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ギュリップス, <SUP>*</SUP>-ポス《Peloponnesus 戦争で活躍した Sparta の将軍》.</div>\r\n","<div class=\"hw\">gymnas</div><div class=\"pos\">-adis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">格闘(競技).</div>\r\n","<div class=\"hw\">gymnasiarchus</div><div class=\"pos\">-ī, <i>m</i>, <B>-a</B> -ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">体育場[体育活動]の監督者.</div>\r\n","<div class=\"hw\">gymnasium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> (ギリシアの)体育場.</div><div class=\"def\"><num>②</num> (ギリシアの)学園.</div>\r\n","<div class=\"hw\">gymnasticus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://gymnicus\">gymnicus<SUP>1</SUP></a>.</div>\r\n","<div class=\"hw\">gymnicus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">体操の, 体育の.</div><hr><div class=\"hw\">gymnicus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">《碑》軽業師, 体育家.</div>\r\n","<div class=\"hw\">gymnosophista</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(インドの)裸行者.</div>\r\n","<div class=\"hw\">gymnospermae</div><div class=\"pos\">-ārum, <SUP>◇</SUP><i>f pl</i></div><div class=\"def\">〘植〙裸子植物類.</div>\r\n","<div class=\"hw\">gynaecologia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘医〙婦人科学.</div>\r\n","<div class=\"hw\">gynaecēum, -īum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> (ギリシアの家の)婦人部屋.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘植〙雌蕊<SUB>しずい</SUB>群.</div>\r\n","<div class=\"hw\">gynaecōnītis</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">=<a href=\"entry://gynaecēum\">gynaeceum</a>.</div>\r\n","<div class=\"hw\">Gyndēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ギュンデース《Tigris 川の支流》.</div>\r\n","<div class=\"hw\">gynostēmium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘植〙蕊柱<SUB>ずいちゅう</SUB>.</div>\r\n","<div class=\"hw\">gypseus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[gypsum]</div><div class=\"def\"><num>①</num> 石膏の.</div><div class=\"def\"><num>②</num> =<a href=\"entry://gypsātus\">gypsatus</a>.</div>\r\n","<div class=\"hw\">gypsoplastēs</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">石膏細工人.</div>\r\n","<div class=\"hw\">gypsum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 石膏</div><div class=\"ex\"><SUP>◇</SUP>～ <i>ustum</i><span class=\"ext\">〘化〙焼石膏.</span></div><div class=\"def\"><num>②</num> 石膏像.</div>\r\n","<div class=\"hw\">gypsārius</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[gypsum]</div><div class=\"def\">石膏細工人.</div>\r\n","<div class=\"hw\">gypsātus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[gypso]</div><div class=\"def\">石膏を塗られて白い.</div>\r\n","<div class=\"hw\">gypsō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[gypsum]</div><div class=\"def\">石膏を塗る.</div>\r\n","<div class=\"hw\">Gyrtōn</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ギュルトーン《Thessalia の Peneus 河畔の町》.</div>\r\n","<div class=\"hw\">gyrīnus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘動〙オタマジャクシ.</div>\r\n","<div class=\"hw\">Gythēum, -ium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ギュテーウム, <SUP>*</SUP>-テイオン《Laconia 南部の港町》.</div>\r\n","<div class=\"hw\">Gyās, -ēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ギュアース, <SUP>*</SUP>ギュエース《 (1) 〘神話〙百腕の巨人.(2) 〘伝説〙Aeneas の仲間》.</div>\r\n","<div class=\"hw\">Gȳgēs</div><div class=\"pos\">-is [-ae], <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ギューゲース《Lydia の王(前7世紀);自らの姿を見えなくさせる指輪を用いて王位を奪ったという》.</div>\r\n","<div class=\"hw\">gȳrovagus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[gyrus/vagus<SUP>1</SUP>]</div><div class=\"def\">さまよっている, さすらいの.</div>\r\n","<div class=\"hw\">gȳrus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 円, 輪</div><div class=\"ex\"><i>gyros per aera ducere</i> (<author>O<small>V</small></author>)<span class=\"ext\">(トビ(鳶)が)空中を旋回する.</span></div><div class=\"def\"><num>②</num> 馬を調教するための円形の走路, 競馬場.</div><div class=\"def\"><num>③</num> 軌道, コース.</div>\r\n","<div class=\"hw\">gȳrō</div><div class=\"pos\">-āre -āvī -ātum, <SUP>◇</SUP><i>tr</i>, <SUP>◇</SUP><i>intr</i></div><div class=\"ori\">[gyrus]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>tr</i>)旋回させる, 回転させる.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>intr</i>)旋回する.</div>\r\n","<div class=\"hw\">Gādēs</div><div class=\"pos\">-ium, <i>f pl</i></div><div class=\"def\">ガーデース《Hispania Baetica の町;現 Cadiz》.</div>\r\n","<div class=\"hw\">Gādītānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Gades の.</div><div class=\"hw2\"><b>Gādītānī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Gades の住民.</div>\r\n","<div class=\"hw\">Gāius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ガイユス《ローマ人の個人名;古くは Caius と綴った(略形は C.)》.</div>\r\n","<div class=\"hw\">Gāiānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Gaius(Caligula)帝の.</div>\r\n","<div class=\"hw\">gānea</div><div class=\"pos\">-ae, <i>f</i>, <B>-um</B> -ī, <i>n</i></div><div class=\"def\">(いかがわしい)飲食店, 居酒屋.</div>\r\n","<div class=\"hw\">gāneō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"ori\">[↑<a href=\"entry://gānea\">gānea</a>]</div><div class=\"def\">飲み屋に入りびたる者, 放蕩者.</div>\r\n","<div class=\"hw\">Gāvius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ガーウィウス《ローマ人の氏族名》.</div>\r\n","<div class=\"hw\">gāvīsus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://gaudeō\">gaudeo</a>.</div>\r\n","<div class=\"hw\">Gēnab</div><div class=\"def\">⇒Cenab-.</div>\r\n","<div class=\"hw\">Gēryonāceus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Geryon の.</div>\r\n","<div class=\"hw\">Gēryonēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">=<a href=\"entry://Gēryōn\">Geryon</a>.</div>\r\n","<div class=\"hw\">Gēryonēus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Geryon の.</div>\r\n","<div class=\"hw\">Gēryōn</div><div class=\"pos\">-onis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘神話〙ゲーリュオーン《Erythea 島に住む三頭三身の怪物;Hercules に殺された》.</div>\r\n","<div class=\"hw\">gēsum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">=<a href=\"entry://gaesum\">gaesum</a>.</div>\r\n","<div class=\"hw\">gēthyum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙アサツキ(=<a href=\"entry://pallacāna\">pallacana</a>).</div>\r\n","<div class=\"hw\">gētīum, -on</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">=<a href=\"entry://gēthyum\">gethyum</a>.</div>\r\n","<div class=\"hw\">Gētūlī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">=<a href=\"entry://Gaetūlī\">Gaetuli</a>.</div>\r\n","<div class=\"hw\">gōbius</div><div class=\"pos\">-ī, <B>gōbiō</B> -ōnis, [<i>Gk</i>] <i>m</i></div><div class=\"def\">〘魚〙タイリクスナモグリ.</div>\r\n","<div class=\"hw\">gōrȳtus, -os</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">=<a href=\"entry://cōrȳtus\">corytus</a>.</div>\r\n","<div class=\"hw\">gūrus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">=<a href=\"entry://gȳrus\">gyrus</a>.</div>\r\n"]);
